const {
  createCategoryRouteHelpers,
} = require('../../features/catalog/productRoutes/categoryHelpers');
const { createCatalogBulkJobsService } = require('../../features/catalog/bulkJobsService');

const createCatalogServices = ({ core, domainCore } = {}) => {
  const { db, requestUtils, libs, configValues, adminAudit, productHelpers } = core;
  const categoryHelpers = createCategoryRouteHelpers({
    dbAllAsync: db.dbAllAsync,
    dbGetAsync: db.dbGetAsync,
    dbRunAsync: db.dbRunAsync,
  });

  const catalogBulkJobs = createCatalogBulkJobsService({
    dbAllAsync: db.dbAllAsync,
    dbGetAsync: db.dbGetAsync,
    dbRunAsync: db.dbRunAsync,
    dbTxAsync: db.dbTxAsync,
    resolveOrCreateCategoryHierarchyAsync: categoryHelpers.resolveOrCreateCategoryHierarchyAsync,
    logAdminAuditAsync: adminAudit.logAdminAuditAsync,
    resolveClientRequestId: requestUtils.resolveClientRequestId,
    normalizeProductInput: productHelpers.normalizeProductInput,
    validateProductPayload: productHelpers.validateProductPayload,
    findProductConflictAsync: productHelpers.findProductConflictAsync,
    buildProductExactKey: productHelpers.buildProductExactKey,
    normalizeTextKey: productHelpers.normalizeTextKey,
    SQL_INSERT_IGNORE_CATEGORY: core.constants.SQL_INSERT_IGNORE_CATEGORY,
    crypto: libs.crypto,
    IS_VERCEL_RUNTIME: configValues.IS_VERCEL_RUNTIME,
  });

  return {
    categoryHelpers,
    catalogBulkJobs,
  };
};

module.exports = { createCatalogServices };

const createUnsupportedModeError = (mode) =>
  new Error(`[DB] DB_EXECUTION_MODE=${mode} is unsupported. Use DB_EXECUTION_MODE=postgres.`);

const createPostgresSyncNotSupportedError = (operation) =>
  new Error(
    `[DB] Postgres adapter does not support synchronous "${operation}". Use async DB helpers.`
  );

const createPostgresPoolNotReadyError = () =>
  new Error(
    '[DB] Postgres pool is not initialized. Check DB_EXECUTION_MODE/DB_CLIENT and SUPABASE/PG connection settings.'
  );

const resolveMode = (value) => {
  const normalized = String(value || '')
    .trim()
    .toLowerCase();
  if (!normalized) return 'postgres';
  if (normalized === 'postgres' || normalized === 'pg' || normalized === 'supabase')
    return 'postgres';
  throw createUnsupportedModeError(normalized);
};

const normalizePostgresRunResult = (result) => ({
  changes: Number(result?.rowCount || 0),
  lastInsertRowid: Number(result?.rows?.[0]?.id || 0),
});

const convertQuestionParamsToPostgres = (sql) => {
  let out = '';
  let index = 1;
  let inSingle = false;
  let inDouble = false;
  let inLineComment = false;
  let inBlockComment = false;

  for (let i = 0; i < sql.length; i += 1) {
    const char = sql[i];
    const next = sql[i + 1];

    if (inLineComment) {
      out += char;
      if (char === '\n') inLineComment = false;
      continue;
    }

    if (inBlockComment) {
      out += char;
      if (char === '*' && next === '/') {
        out += next;
        i += 1;
        inBlockComment = false;
      }
      continue;
    }

    if (!inSingle && !inDouble) {
      if (char === '-' && next === '-') {
        out += char + next;
        i += 1;
        inLineComment = true;
        continue;
      }
      if (char === '/' && next === '*') {
        out += char + next;
        i += 1;
        inBlockComment = true;
        continue;
      }
    }

    if (char === "'" && !inDouble) {
      out += char;
      if (inSingle && next === "'") {
        out += next;
        i += 1;
      } else {
        inSingle = !inSingle;
      }
      continue;
    }
    if (char === '"' && !inSingle) {
      inDouble = !inDouble;
      out += char;
      continue;
    }

    if (char === '?' && !inSingle && !inDouble) {
      out += `$${index}`;
      index += 1;
      continue;
    }

    out += char;
  }

  return out;
};

const appendReturningIdIfInsert = (sql) => {
  const trimmed = String(sql || '').trim();
  if (!/^insert\s+into\s+/i.test(trimmed)) return sql;
  if (/\breturning\b/i.test(trimmed)) return sql;
  if (/;\s*$/.test(sql)) return sql.replace(/;\s*$/, ' RETURNING id;');
  return `${sql} RETURNING id`;
};

const createPostgresQueryAdapter = ({ getPostgresPool }) => {
  const withPool = async (handler) => {
    const pool = typeof getPostgresPool === 'function' ? getPostgresPool() : null;
    if (!pool) throw createPostgresPoolNotReadyError();
    return handler(pool);
  };

  const execute = async (runner, sql, params = [], { forRun = false } = {}) => {
    const transformed = convertQuestionParamsToPostgres(
      forRun ? appendReturningIdIfInsert(sql) : sql
    );
    return runner.query(transformed, params);
  };

  return {
    mode: 'postgres',
    run: () => {
      throw createPostgresSyncNotSupportedError('run');
    },
    runAsync: async (sql, params = []) =>
      withPool(async (pool) => {
        const result = await execute(pool, sql, params, { forRun: true });
        return normalizePostgresRunResult(result);
      }),
    get: () => {
      throw createPostgresSyncNotSupportedError('get');
    },
    getAsync: async (sql, params = []) =>
      withPool(async (pool) => {
        const result = await execute(pool, sql, params);
        return result?.rows?.[0];
      }),
    all: () => {
      throw createPostgresSyncNotSupportedError('all');
    },
    allAsync: async (sql, params = []) =>
      withPool(async (pool) => {
        const result = await execute(pool, sql, params);
        return result?.rows || [];
      }),
    prepare: () => {
      throw createPostgresSyncNotSupportedError('prepare');
    },
    transaction:
      () =>
      (..._args) => {
        throw createPostgresSyncNotSupportedError('transaction');
      },
    transactionAsync: async (handler, ...args) =>
      withPool(async (pool) => {
        const connection = await pool.connect();
        const tx = {
          runAsync: async (sql, params = []) => {
            const result = await execute(connection, sql, params, { forRun: true });
            return normalizePostgresRunResult(result);
          },
          getAsync: async (sql, params = []) => {
            const result = await execute(connection, sql, params);
            return result?.rows?.[0];
          },
          allAsync: async (sql, params = []) => {
            const result = await execute(connection, sql, params);
            return result?.rows || [];
          },
        };
        try {
          await connection.query('BEGIN');
          const result = await handler(tx, ...args);
          await connection.query('COMMIT');
          return result;
        } catch (error) {
          try {
            await connection.query('ROLLBACK');
          } catch (_) {
            // ignore rollback failures
          }
          throw error;
        } finally {
          connection.release();
        }
      }),
  };
};

const createQueryAdapter = ({ mode = 'postgres', getPostgresPool = null }) => {
  const resolvedMode = resolveMode(mode);
  if (resolvedMode === 'postgres') {
    return createPostgresQueryAdapter({ getPostgresPool });
  }
  throw createUnsupportedModeError(resolvedMode);
};

module.exports = {
  createQueryAdapter,
};

const registerContactVerificationRoutes = (deps) => {
  const {
    app,
    requireAuth,
    authIpLimiter,
    emailVerificationLimiter,
    requireInternalCron,
    dbGetAsync,
    dbRunAsync,
    dbAllAsync,
    normalizeEmail,
    parsePhoneInput,
    normalizePhone,
    hashPassword,
    generateTemporaryPassword,
    isUniqueViolationError,
    generateOtpCode,
    OTP_TTL_SECONDS,
    OTP_MAX_ATTEMPTS,
    notificationService,
    createNotificationEvent,
    EMAIL_DELIVERY_MODE,
    emailVerificationProvider,
    updateNotificationEventStatus,
    AUTH_LOGIN_OTP_EXPOSE_CODE,
    isSupabaseEmailAuthUsable,
    supabaseAuthProvider,
    syncLocalUserFromSupabaseAuth,
    getSupabaseUserMetadata,
    sanitizeUser,
    generateToken,
    toSupabaseSessionPayload,
    verifyPassword,
    isSupabaseAuthStrictMode,
    queueContactVerificationRequest,
    getRequestIp,
    syncLocalEmailVerifiedFromSupabase,
    completeContactVerificationRequests,
    EMAIL_VERIFY_MAX_ATTEMPTS,
    hashVerificationToken,
    getBearerTokenFromRequest,
    isSupabaseEmailVerified,
    EMAIL_VERIFICATION_MODE,
    SUPABASE_AUTH_MODE,
    WHATSAPP_DELIVERY_MODE,
    whatsappProvider,
    processPendingPhoneChangeRequests,
    getLatestPhoneChangeRequestForUser,
    serializePhoneChangeRequest,
    getOpenPhoneChangeRequestForUser,
    rejectPhoneChangeRequest,
    createAppNotification,
    PHONE_CHANGE_STATUS_REJECTED,
    PHONE_CHANGE_AUTO_BATCH_SIZE,
    normalizeContactVerificationRequestType,
    AUTH_FLOW_MODE,
    OTP_PROVIDER,
    OTP_DELIVERY_MODE,
    OTP_VERIFY_SESSION_TTL_SECONDS,
    PHONE_VERIFICATION_REQUIRED,
    WHATSAPP_PROVIDER,
    SUPABASE_EMAIL_VERIFY_REDIRECT,
    PHONE_VERIFY_MAX_ATTEMPTS,
    hashOpaqueToken,
  } = deps;

  app.get('/api/auth/contact-verification/status', requireAuth, async (req, res) => {
    try {
      const userId = Number(req.authUser?.id || 0);
      if (!userId) return res.status(401).json({ error: 'Unauthorized' });

      const rows = await dbAllAsync(
        `SELECT id, request_type, status, admin_note, processed_at, completed_at, created_at, updated_at
       FROM contact_verification_requests
       WHERE user_id = ?
       ORDER BY id DESC`,
        [userId]
      );

      const latest = { email: null, phone: null };
      rows.forEach((row) => {
        const type = normalizeContactVerificationRequestType(row?.request_type);
        if (!type || latest[type]) return;
        latest[type] = row;
      });

      return res.json(latest);
    } catch (error) {
      return res
        .status(500)
        .json({ error: error.message || 'Failed to load verification request status' });
    }
  });

  app.post('/api/auth/phone/verification/request-self', requireAuth, async (req, res) => {
    try {
      const user = await dbGetAsync(
        `SELECT id, name, phone, phone_verified FROM users WHERE id = ?`,
        [req.authUser.id]
      );
      if (!user) return res.status(404).json({ error: 'User not found' });
      const normalizedPhone = normalizePhone(user.phone);
      if (!normalizedPhone) {
        return res.status(400).json({ error: 'No phone is set on your profile' });
      }
      if (Number(user.phone_verified || 0) === 1) {
        return res.status(200).json({ success: true, message: 'Phone is already verified' });
      }
      const requestRow = await queueContactVerificationRequest({
        userId: user.id,
        requestedBy: Number(req.authUser?.id || 0) || null,
        requestedFromIp: getRequestIp(req),
        requestType: 'phone',
      });
      return res.status(201).json({
        success: true,
        message: 'Phone verification request submitted to admin',
        request: requestRow,
      });
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });
};

module.exports = { registerContactVerificationRoutes };

const registerCustomerRoutes = (deps) => {
  const {
    app,
    requireAdmin,
    requireAuth,
    dbGetAsync,
    dbRunAsync,
    dbAllAsync,
    normalizeEmail,
    parsePhoneInput,
    normalizePhone,
    parseBooleanEnv,
    runCustomerRequestPurge,
    processPendingPhoneChangeRequests,
    getPhoneMergeImpactSummary,
    serializePhoneChangeRequest,
    PHONE_CHANGE_STATUS_PENDING,
    PHONE_CHANGE_STATUS_APPROVED,
    PHONE_CHANGE_STATUS_REJECTED,
    normalizePhoneChangeRequestStatus,
    approvePhoneChangeRequest,
    PHONE_CHANGE_DECISION_ADMIN,
    notifyPhoneChangeApproved,
    notifyPhoneChangeSubmitted,
    logAdminAuditAsync,
    rejectPhoneChangeRequest,
    notifyPhoneChangeRejected,
    normalizeContactVerificationRequestType,
    completeContactVerificationRequests,
    sendEmailVerificationChallenge,
    markContactVerificationRequestSent,
    sendPhoneVerificationChallenge,
    rejectContactVerificationRequest,
    createNotificationEvent,
    sanitizeUser,
    generateTemporaryPassword,
    hashPassword,
    queuePhoneChangeRequest,
    getRequestIp,
    parseDataUrlImage,
    PROFILE_IMAGE_ALLOWED_MIME,
    PROFILE_IMAGE_MAX_BYTES,
    mimeToExt,
    buildProfileImagePath,
    deleteManagedProfileImage,
    PROFILE_UPLOAD_DIR,
    crypto,
    path,
    fs,
    validateCustomerProfile,
  } = deps;

  app.get('/api/customers', requireAdmin, async (_, res) => {
    try {
      const customers = await dbAllAsync(
        `SELECT id, name, email, phone, address, profile_image, created_at FROM users WHERE role = 'customer' ORDER BY name ASC`
      );
      return res.json(customers);
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });

  app.get('/api/customers/search', requireAdmin, async (req, res) => {
    try {
      const q = String(req.query.q || req.query.name || '').trim();
      const limit = Number(req.query.limit || 20);
      if (!q) {
        const rows = await dbAllAsync(
          `SELECT id, name, email, phone, address, profile_image, created_at FROM users WHERE role='customer' ORDER BY name LIMIT ?`,
          [limit]
        );
        return res.json(rows);
      }
      const like = `%${q}%`;
      const rows = await dbAllAsync(
        `SELECT id, name, email, phone, address, profile_image, created_at
         FROM users
         WHERE role='customer' AND (name LIKE ? OR email LIKE ? OR phone LIKE ?)
         ORDER BY name LIMIT ?`,
        [like, like, like, limit]
      );
      return res.json(rows);
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });

  app.get('/api/customers/:id/profile', requireAuth, async (req, res) => {
    try {
      const targetUserId = Number(req.params.id);
      if (!targetUserId) return res.status(400).json({ error: 'Invalid customer id' });
      if (req.authUser.role !== 'admin' && Number(req.authUser.id) !== targetUserId) {
        return res.status(403).json({ error: 'Forbidden' });
      }
      const user = await dbGetAsync(
        `SELECT id, name, email, email_verified, phone, phone_verified, address, profile_image, role FROM users WHERE id = ?`,
        [req.params.id]
      );
      if (!user) return res.status(404).json({ error: 'Customer not found' });
      let address = {};
      if (user.address) {
        try {
          address = JSON.parse(user.address);
        } catch (_) {
          address = { street: user.address };
        }
      }
      return res.json({
        ...user,
        address,
        profileComplete: validateCustomerProfile(user, address),
      });
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });
};

module.exports = { registerCustomerRoutes };

const registerCustomerValidationRoutes = (deps) => {
  const {
    app,
    requireAdmin,
    requireAuth,
    dbGetAsync,
    dbRunAsync,
    dbAllAsync,
    normalizeEmail,
    parsePhoneInput,
    normalizePhone,
    parseBooleanEnv,
    runCustomerRequestPurge,
    processPendingPhoneChangeRequests,
    getPhoneMergeImpactSummary,
    serializePhoneChangeRequest,
    PHONE_CHANGE_STATUS_PENDING,
    PHONE_CHANGE_STATUS_APPROVED,
    PHONE_CHANGE_STATUS_REJECTED,
    normalizePhoneChangeRequestStatus,
    approvePhoneChangeRequest,
    PHONE_CHANGE_DECISION_ADMIN,
    notifyPhoneChangeApproved,
    notifyPhoneChangeSubmitted,
    logAdminAuditAsync,
    rejectPhoneChangeRequest,
    notifyPhoneChangeRejected,
    normalizeContactVerificationRequestType,
    completeContactVerificationRequests,
    sendEmailVerificationChallenge,
    markContactVerificationRequestSent,
    sendPhoneVerificationChallenge,
    rejectContactVerificationRequest,
    createNotificationEvent,
    sanitizeUser,
    generateTemporaryPassword,
    hashPassword,
    queuePhoneChangeRequest,
    getRequestIp,
    parseDataUrlImage,
    PROFILE_IMAGE_ALLOWED_MIME,
    PROFILE_IMAGE_MAX_BYTES,
    mimeToExt,
    buildProfileImagePath,
    deleteManagedProfileImage,
    PROFILE_UPLOAD_DIR,
    crypto,
    path,
    fs,
    validateCustomerProfile,
  } = deps;

  app.post('/api/orders/validate-customer', requireAuth, async (req, res) => {
    try {
      const userId = Number(req.body?.user_id || 0);
      if (!userId)
        return res
          .status(400)
          .json({ error: 'MISSING_CUSTOMER', message: 'Customer ID is required' });
      if (req.authUser.role !== 'admin' && Number(req.authUser.id) !== userId) {
        return res.status(403).json({ error: 'Forbidden' });
      }
      const user = await dbGetAsync(
        `SELECT id, name, email, email_verified, phone, phone_verified, address, role FROM users WHERE id = ?`,
        [userId]
      );
      if (!user)
        return res.status(404).json({ error: 'CUSTOMER_NOT_FOUND', message: 'Customer not found' });
      let address = {};
      if (user.address) {
        try {
          address = JSON.parse(user.address);
        } catch (_) {
          address = { street: user.address };
        }
      }
      const validation = validateCustomerProfile(user, address);
      return res.json({
        valid: validation.complete,
        isAdmin: user.role === 'admin',
        profile: {
          id: user.id,
          name: user.name,
          email: user.email,
          email_verified: Number(user.email_verified || 0) === 1,
          phone: user.phone,
          phone_verified: Number(user.phone_verified || 0) === 1,
          address,
        },
        validation,
      });
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });
};

module.exports = { registerCustomerValidationRoutes };

const registerEmailVerificationStatusRoutes = (deps) => {
  const {
    app,
    requireAuth,
    dbGetAsync,
    normalizeEmail,
    getBearerTokenFromRequest,
    isSupabaseEmailAuthUsable,
    isSupabaseEmailVerified,
    supabaseAuthProvider,
    syncLocalEmailVerifiedFromSupabase,
    completeContactVerificationRequests,
    EMAIL_VERIFICATION_MODE,
    emailVerificationProvider,
    SUPABASE_AUTH_MODE,
  } = deps;

  app.get('/api/auth/email/verification/status', requireAuth, async (req, res) => {
    try {
      let user = await dbGetAsync('SELECT id, email, email_verified FROM users WHERE id = ?', [
        req.authUser.id,
      ]);
      if (!user) return res.status(404).json({ error: 'User not found' });
      if (isSupabaseEmailAuthUsable() && user.email) {
        const bearerToken = getBearerTokenFromRequest(req);
        if (bearerToken) {
          try {
            const supabaseUser = await supabaseAuthProvider.getUser({ accessToken: bearerToken });
            if (isSupabaseEmailVerified(supabaseUser) && Number(user.email_verified || 0) !== 1) {
              await syncLocalEmailVerifiedFromSupabase(user.email);
              user =
                (await dbGetAsync('SELECT id, email, email_verified FROM users WHERE id = ?', [
                  req.authUser.id,
                ])) || user;
              await completeContactVerificationRequests({ userId: user.id, requestType: 'email' });
            }
          } catch (_) {
            // Ignore token mismatch (legacy token) and keep local status.
          }
        }
      }
      return res.json({
        email: user.email || null,
        email_verified: Number(user.email_verified || 0) === 1,
        mode: EMAIL_VERIFICATION_MODE,
        provider_ready: Boolean(emailVerificationProvider?.isReady),
        provider: isSupabaseEmailAuthUsable() ? 'supabase' : 'legacy',
        supabase_auth_enabled: Boolean(supabaseAuthProvider?.isEnabled),
        supabase_auth_mode: SUPABASE_AUTH_MODE,
        supabase_client_ready: Boolean(supabaseAuthProvider?.clientReady),
        supabase_admin_ready: Boolean(supabaseAuthProvider?.adminReady),
      });
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });
};

module.exports = { registerEmailVerificationStatusRoutes };

const crypto = require('crypto');

const timingSafeEqualString = (left, right) => {
  const leftValue = String(left || '');
  const rightValue = String(right || '');
  if (!leftValue || !rightValue) return false;
  const leftBuffer = Buffer.from(leftValue);
  const rightBuffer = Buffer.from(rightValue);
  if (leftBuffer.length !== rightBuffer.length) return false;
  return crypto.timingSafeEqual(leftBuffer, rightBuffer);
};

const registerPhoneVerificationRoutes = (deps) => {
  const {
    app,
    requireAuth,
    authIpLimiter,
    emailVerificationLimiter,
    requireInternalCron,
    dbGetAsync,
    dbRunAsync,
    dbAllAsync,
    normalizeEmail,
    parsePhoneInput,
    normalizePhone,
    hashPassword,
    generateTemporaryPassword,
    isUniqueViolationError,
    generateOtpCode,
    OTP_TTL_SECONDS,
    OTP_MAX_ATTEMPTS,
    notificationService,
    createNotificationEvent,
    EMAIL_DELIVERY_MODE,
    emailVerificationProvider,
    updateNotificationEventStatus,
    AUTH_LOGIN_OTP_EXPOSE_CODE,
    isSupabaseEmailAuthUsable,
    supabaseAuthProvider,
    syncLocalUserFromSupabaseAuth,
    getSupabaseUserMetadata,
    sanitizeUser,
    generateToken,
    toSupabaseSessionPayload,
    verifyPassword,
    isSupabaseAuthStrictMode,
    queueContactVerificationRequest,
    getRequestIp,
    syncLocalEmailVerifiedFromSupabase,
    completeContactVerificationRequests,
    EMAIL_VERIFY_MAX_ATTEMPTS,
    hashVerificationToken,
    getBearerTokenFromRequest,
    isSupabaseEmailVerified,
    EMAIL_VERIFICATION_MODE,
    SUPABASE_AUTH_MODE,
    WHATSAPP_DELIVERY_MODE,
    whatsappProvider,
    processPendingPhoneChangeRequests,
    getLatestPhoneChangeRequestForUser,
    serializePhoneChangeRequest,
    getOpenPhoneChangeRequestForUser,
    rejectPhoneChangeRequest,
    createAppNotification,
    PHONE_CHANGE_STATUS_REJECTED,
    PHONE_CHANGE_AUTO_BATCH_SIZE,
    normalizeContactVerificationRequestType,
    AUTH_FLOW_MODE,
    OTP_PROVIDER,
    OTP_DELIVERY_MODE,
    OTP_VERIFY_SESSION_TTL_SECONDS,
    PHONE_VERIFICATION_REQUIRED,
    WHATSAPP_PROVIDER,
    SUPABASE_EMAIL_VERIFY_REDIRECT,
    PHONE_VERIFY_MAX_ATTEMPTS,
    hashOpaqueToken,
  } = deps;

  app.post('/api/auth/phone/verification/request', authIpLimiter, async (req, res) => {
    try {
      const phoneParsed = parsePhoneInput(req.body?.phone, { required: true });
      if (phoneParsed.error) return res.status(400).json({ error: phoneParsed.error });
      const normalizedPhone = phoneParsed.value;
      const user = await dbGetAsync(
        `SELECT id, name, phone, phone_verified FROM users WHERE phone = ?`,
        [normalizedPhone]
      );
      if (!user) {
        return res.status(201).json({
          success: true,
          message: 'If the account exists, verification request was submitted for admin review.',
        });
      }
      if (Number(user.phone_verified || 0) === 1) {
        return res.status(200).json({ success: true, message: 'Phone is already verified' });
      }
      const requestRow = await queueContactVerificationRequest({
        userId: user.id,
        requestType: 'phone',
        requestedFromIp: getRequestIp(req),
      });
      return res.status(201).json({
        success: true,
        message: 'Phone verification request submitted to admin',
        request: requestRow,
      });
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });

  app.post('/api/auth/phone/verification/confirm', authIpLimiter, async (req, res) => {
    try {
      const phoneParsed = parsePhoneInput(req.body?.phone, { required: true });
      if (phoneParsed.error) return res.status(400).json({ error: phoneParsed.error });
      const normalizedPhone = phoneParsed.value;
      const code = String(req.body?.code || req.body?.token || '').trim();
      if (!code) return res.status(400).json({ error: 'Phone and code are required' });
      const user = await dbGetAsync(`SELECT id, phone_verified FROM users WHERE phone = ?`, [
        normalizedPhone,
      ]);
      if (!user) return res.status(400).json({ error: 'Invalid or expired verification code' });
      if (Number(user.phone_verified || 0) === 1) {
        await completeContactVerificationRequests({ userId: user.id, requestType: 'phone' });
        return res.json({ success: true, message: 'Phone is already verified' });
      }

      const tokenRow = await dbGetAsync(
        `SELECT * FROM phone_verification_tokens
       WHERE user_id = ? AND phone = ? AND used = 0
       ORDER BY id DESC LIMIT 1`,
        [user.id, normalizedPhone]
      );
      if (!tokenRow) return res.status(400).json({ error: 'Invalid or expired verification code' });

      const now = Date.now();
      const expiresAt = new Date(tokenRow.expires_at).getTime();
      if (!Number.isFinite(expiresAt) || now > expiresAt) {
        await dbRunAsync(`UPDATE phone_verification_tokens SET used = 1 WHERE id = ?`, [
          tokenRow.id,
        ]);
        return res.status(400).json({ error: 'Invalid or expired verification code' });
      }
      if (
        Number(tokenRow.attempts || 0) >= Number(tokenRow.max_attempts || PHONE_VERIFY_MAX_ATTEMPTS)
      ) {
        await dbRunAsync(`UPDATE phone_verification_tokens SET used = 1 WHERE id = ?`, [
          tokenRow.id,
        ]);
        return res.status(400).json({ error: 'Verification code attempt limit reached' });
      }

      const providedHash = hashOpaqueToken(code);
      if (!timingSafeEqualString(providedHash, tokenRow.token_hash)) {
        const nextAttempts = Number(tokenRow.attempts || 0) + 1;
        const exhausted =
          nextAttempts >= Number(tokenRow.max_attempts || PHONE_VERIFY_MAX_ATTEMPTS);
        await dbRunAsync(
          `UPDATE phone_verification_tokens SET attempts = ?, used = ? WHERE id = ?`,
          [nextAttempts, exhausted ? 1 : Number(tokenRow.used || 0), tokenRow.id]
        );
        return res.status(400).json({ error: 'Invalid or expired verification code' });
      }

      await dbRunAsync(`UPDATE users SET phone_verified = 1 WHERE id = ?`, [user.id]);
      await dbRunAsync(
        `UPDATE phone_verification_tokens SET used = 1 WHERE user_id = ? AND phone = ? AND used = 0`,
        [user.id, normalizedPhone]
      );
      await completeContactVerificationRequests({ userId: user.id, requestType: 'phone' });
      return res.json({ success: true, message: 'Phone verified successfully' });
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });

  app.get('/api/auth/phone/verification/status', requireAuth, async (req, res) => {
    try {
      const user = await dbGetAsync(`SELECT id, phone, phone_verified FROM users WHERE id = ?`, [
        req.authUser.id,
      ]);
      if (!user) return res.status(404).json({ error: 'User not found' });
      const providerSupportsSend = Boolean(whatsappProvider?.supportsSend);
      return res.json({
        phone: user.phone || null,
        phone_verified: Number(user.phone_verified || 0) === 1,
        mode: WHATSAPP_DELIVERY_MODE,
        delivery_scope: providerSupportsSend ? 'provider_send' : 'manual_prepare',
        provider_supports_send: providerSupportsSend,
        provider_ready: providerSupportsSend && Boolean(whatsappProvider?.isReady),
      });
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });
};

