const registerUserProfileRoutes = (deps) => {
  const {
    app,
    requireAuth,
    userHasCapability,
    dbGetAsync,
    dbRunAsync,
    normalizeEmail,
    parsePhoneInput,
    normalizePhone,
    sendEmailVerificationChallenge,
