    PROFILE_IMAGE_MAX_BYTES,
    mimeToExt,
    buildProfileImagePath,
    deleteManagedProfileImage,
    profileImageStorage,
    PROFILE_UPLOAD_DIR,
    crypto,
    path,
    fs,
  } = deps;

  app.get('/api/users/:id', requireAuth, async (req, res) => {
