const buildHierarchyPath = (parent, child) => {
  const root = String(parent || '').trim();
  const leaf = String(child || '').trim();
  if (!root) return '';
  if (!leaf) return root;
  return `${root} -> ${leaf}`;
};

const normalizeQueryText = (value, maxLength = 160) =>
  String(value || '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, maxLength);

const escapeLikePattern = (value) => String(value || '').replace(/[\\%_]/g, '\\$&');

const splitHierarchyFilter = (value) => {
  const raw = normalizeQueryText(value);
  if (!raw) return { parent: '', child: '' };
  const parts = raw
    .split(/\s*(?:->|\/)\s*/)
    .map((part) => String(part || '').trim())
    .filter(Boolean);
  if (parts.length === 0) return { parent: '', child: '' };
  if (parts.length === 1) return { parent: parts[0], child: '' };
  return {
    parent: parts[0],
    child: parts.slice(1).join(' -> '),
  };
};

const normalizeSortField = (value) => {
  const raw = String(value || '').trim();
  const aliases = {
    default_discount: 'defaultDiscount',
    defaultdiscount: 'defaultDiscount',
    purchasepacksize: 'purchase_pack_size',
    purchase_pack_size: 'purchase_pack_size',
    purchasePackSize: 'purchase_pack_size',
  };
  if (!raw) return '';
  const normalized = aliases[raw] || raw;
  const lower = normalized.toLowerCase();
  if (lower === 'defaultdiscount') return 'defaultDiscount';
  if (lower === 'purchasepacksize') return 'purchase_pack_size';
  return normalized;
};

const normalizeSortDir = (value) => {
  const raw = String(value || '')
    .trim()
    .toLowerCase();
  if (raw === 'asc' || raw === 'ascending') return 'asc';
  if (raw === 'desc' || raw === 'descending') return 'desc';
  return '';
};

const PRODUCT_EXPORT_SORT_SPECS = {
  created_at: { expr: "COALESCE(p.created_at, TIMESTAMPTZ '1970-01-01 00:00:00+00')" },
  id: { expr: 'COALESCE(p.id, 0)' },
  name: { expr: "LOWER(COALESCE(p.name, ''))" },
  brand: {
    expr: "LOWER(TRIM(COALESCE(p.brand, '') || CASE WHEN COALESCE(p.sub_brand, '') = '' THEN '' ELSE ' -> ' || COALESCE(p.sub_brand, '') END))",
  },
  category: {
    expr: "LOWER(TRIM(COALESCE(p.category, '') || CASE WHEN COALESCE(p.subcategory, '') = '' THEN '' ELSE ' -> ' || COALESCE(p.subcategory, '') END))",
  },
  price: { expr: 'COALESCE(p.price, 0)' },
  mrp: { expr: 'COALESCE(p.mrp, 0)' },
  stock: { expr: 'COALESCE(p.stock, 0)' },
  sku: { expr: "LOWER(COALESCE(p.sku, ''))" },
  barcode: { expr: "LOWER(COALESCE(p.barcode, ''))" },
  is_active: { expr: 'COALESCE(p.is_active, 1)' },
  defaultDiscount: { expr: 'COALESCE(p.default_discount, 0)' },
  purchase_pack_size: { expr: 'COALESCE(p.purchase_pack_size, 0)' },
};

const registerProductExportRoutes = (deps) => {
  const { app, requireAdmin, dbAllAsync, XLSX, toProductExportRow, PRODUCT_IMPORT_HEADERS } = deps;

  app.get('/api/products/export', requireAdmin, async (req, res) => {
    try {
      const format = String(req.query?.format || 'csv')
        .trim()
        .toLowerCase();
      const mode = String(req.query?.mode || 'current')
        .trim()
        .toLowerCase();
      const includeInactive =
        mode === 'all'
          ? true
          : String(req.query?.include_inactive || '')
              .trim()
              .toLowerCase() === 'true';
      const applyFilters = mode !== 'all';
      const searchQuery = applyFilters
        ? normalizeQueryText(req.query?.q || req.query?.name || '').toLowerCase()
        : '';
      const categoryQuery = applyFilters ? normalizeQueryText(req.query?.category || '') : '';
      const brandQuery = applyFilters ? normalizeQueryText(req.query?.brand || '') : '';
      const rawStatus = applyFilters
        ? String(req.query?.status || '')
            .trim()
            .toLowerCase()
        : '';
      const lowStockOnly =
        applyFilters &&
        String(req.query?.low_stock || '')
          .trim()
          .toLowerCase() === 'true';
      const sortField = normalizeSortField(req.query?.sort_field || '') || 'created_at';
      const sortDir =
        normalizeSortDir(req.query?.sort_dir || '') ||
        (sortField === 'name' ||
        sortField === 'brand' ||
        sortField === 'category' ||
        sortField === 'sku'
          ? 'asc'
          : 'desc');

      const whereClauses = ['1=1'];
      const whereParams = [];

      if (rawStatus === 'active') {
        whereClauses.push('COALESCE(p.is_active, 1) = 1');
      } else if (rawStatus === 'inactive') {
        whereClauses.push('COALESCE(p.is_active, 1) = 0');
      } else if (!includeInactive) {
        whereClauses.push('COALESCE(p.is_active, 1) = 1');
      }

      if (rawStatus === 'available') {
        whereClauses.push('COALESCE(p.is_active, 1) = 1');
        whereClauses.push('COALESCE(p.stock, 0) > 0');
      } else if (rawStatus === 'out_of_stock') {
        whereClauses.push('COALESCE(p.is_active, 1) = 1');
        whereClauses.push('COALESCE(p.stock, 0) <= 0');
      }

      if (searchQuery) {
        whereClauses.push("COALESCE(p.search_text, '') LIKE ? ESCAPE '\\'");
        whereParams.push(`%${escapeLikePattern(searchQuery)}%`);
      }

      if (categoryQuery) {
        const categoryParts = splitHierarchyFilter(categoryQuery);
        if (categoryParts.parent) {
          whereClauses.push("LOWER(COALESCE(p.category, '')) = LOWER(?)");
          whereParams.push(categoryParts.parent);
        }
        if (categoryParts.child) {
          whereClauses.push("LOWER(COALESCE(p.subcategory, '')) = LOWER(?)");
          whereParams.push(categoryParts.child);
        }
      }

      if (brandQuery) {
        const brandParts = splitHierarchyFilter(brandQuery);
        if (brandParts.parent) {
          whereClauses.push("LOWER(COALESCE(p.brand, '')) = LOWER(?)");
          whereParams.push(brandParts.parent);
        }
        if (brandParts.child) {
          whereClauses.push("LOWER(COALESCE(p.sub_brand, '')) = LOWER(?)");
          whereParams.push(brandParts.child);
        }
      }

      if (lowStockOnly) {
        whereClauses.push('COALESCE(p.stock, 0) <= 10');
      }

      const sortSpec = PRODUCT_EXPORT_SORT_SPECS[sortField] || PRODUCT_EXPORT_SORT_SPECS.created_at;
      const orderSql = ` ORDER BY ${sortSpec.expr} ${sortDir.toUpperCase()}, p.id ${sortDir.toUpperCase()}`;
      const rows = (
        await dbAllAsync(
          `SELECT * FROM products p WHERE ${whereClauses.join(' AND ')}${orderSql}`,
          whereParams
        )
      ).map(toProductExportRow);

      if (format === 'xlsx' || format === 'xls') {
        const sheet = XLSX.utils.json_to_sheet(rows, { header: PRODUCT_IMPORT_HEADERS });
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, sheet, 'Products');
        const buffer = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
        res.setHeader(
          'Content-Type',
          'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        );
        res.setHeader(
          'Content-Disposition',
          `attachment; filename="products-export-${new Date().toISOString().slice(0, 10)}.xlsx"`
        );
        return res.send(buffer);
      }
      const csv = XLSX.utils.sheet_to_csv(
        XLSX.utils.json_to_sheet(rows, { header: PRODUCT_IMPORT_HEADERS })
      );
      res.setHeader('Content-Type', 'text/csv; charset=utf-8');
      res.setHeader(
        'Content-Disposition',
        `attachment; filename="products-export-${new Date().toISOString().slice(0, 10)}.csv"`
      );
      return res.send(`\uFEFF${csv}`);
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });
};

module.exports = { registerProductExportRoutes };

const registerProductImportPreviewRoutes = (deps) => {
  const {
    app,
    requireAdmin,
    dbRunAsync,
    cleanupExpiredImportBatches,
    parseProductFileToRows,
    findExistingProductForImportAsync,
    normalizeProductInput,
    validateProductPayload,
    findProductConflictAsync,
    normalizeTextKey,
    buildProductExactKey,
    crypto,
    createImportBatchChecksum,
    PRODUCT_IMPORT_BATCH_TTL_MS,
    productImportBatches,
    SQL_UPSERT_IMPORT_BATCH,
    catalogBulkJobs,
  } = deps;
  const { queueImportBulkJobFromBatchAsync } = require('./importBulkJobHelpers');

  app.post('/api/products/import/preview', requireAdmin, async (req, res) => {
    try {
      cleanupExpiredImportBatches();
      const mode = String(req.body?.mode || 'upsert')
        .trim()
        .toLowerCase();
      const stockMode = String(req.body?.stock_mode || 'replace')
        .trim()
        .toLowerCase();
      if (!['create_only', 'update_only', 'upsert'].includes(mode)) {
        return res
          .status(400)
          .json({ error: 'Invalid mode. Use create_only, update_only or upsert' });
      }
      if (!['replace', 'delta'].includes(stockMode)) {
        return res.status(400).json({ error: 'Invalid stock_mode. Use replace or delta' });
      }

      const rows = parseProductFileToRows({
        fileName: req.body?.file_name,
        fileContentBase64: req.body?.file_content_base64,
      });

      const normalizedRows = [];
      const preview = [];
      let creates = 0;
      let updates = 0;
      let skips = 0;
      let errors = 0;
      let needsConfirmation = 0;
      const seenInBatch = {
        productIds: new Map(),
        sku: new Map(),
        barcode: new Map(),
        identity: new Map(),
      };

      for (let index = 0; index < rows.length; index += 1) {
        const row = rows[index];
        const rowNo = index + 2;
        const existing = await findExistingProductForImportAsync(row);
        const action = existing ? 'update' : 'create';
        const normalized = normalizeProductInput(
          {
            ...row,
            stock:
              stockMode === 'delta' && existing
                ? Number(existing.stock || 0) + Number(row.stock || 0)
                : row.stock,
          },
          existing || null
        );
        const rowErrors = validateProductPayload(normalized);

        if (mode === 'create_only' && existing)
          rowErrors.push('Row matches existing product but mode is create_only');
        if (mode === 'update_only' && !existing)
          rowErrors.push('Row does not match an existing product but mode is update_only');
        const duplicate = await findProductConflictAsync(normalized, {
          excludeId: existing?.id || null,
        });
        let requiresIdenticalConfirmation = false;
        let warnings = [];
        if (duplicate) {
          if (duplicate.severity === 'confirm') {
            requiresIdenticalConfirmation = true;
            warnings = [duplicate.message];
          } else {
            rowErrors.push(duplicate.message);
          }
        }

        const matchedId = existing?.id ? Number(existing.id) : null;
        if (matchedId) {
          const seenProductRow = seenInBatch.productIds.get(matchedId);
          if (seenProductRow)
            rowErrors.push(`Duplicate update target in import file (also row ${seenProductRow})`);
        }
        const skuKey = normalizeTextKey(normalized.sku);
        if (skuKey) {
          const seenSkuRow = seenInBatch.sku.get(skuKey);
          if (seenSkuRow) rowErrors.push(`Duplicate SKU in import file (also row ${seenSkuRow})`);
        }
        const barcodeKey = normalizeTextKey(normalized.barcode);
        if (barcodeKey) {
          const seenBarcodeRow = seenInBatch.barcode.get(barcodeKey);
          if (seenBarcodeRow)
            rowErrors.push(`Duplicate barcode in import file (also row ${seenBarcodeRow})`);
        }
        const identityKey = buildProductExactKey(normalized);
        if (identityKey) {
          const seenIdentityRow = seenInBatch.identity.get(identityKey);
          if (seenIdentityRow)
            rowErrors.push(`Exact duplicate in import file (also row ${seenIdentityRow})`);
        }

        if (rowErrors.length) {
          errors += 1;
          preview.push({
            row: rowNo,
            action,
            status: 'error',
            errors: rowErrors,
            matched_product_id: existing?.id || null,
          });
          continue;
        }

        if (matchedId) seenInBatch.productIds.set(matchedId, rowNo);
        if (skuKey) seenInBatch.sku.set(skuKey, rowNo);
        if (barcodeKey) seenInBatch.barcode.set(barcodeKey, rowNo);
        if (identityKey) seenInBatch.identity.set(identityKey, rowNo);

        normalizedRows.push({
          row: rowNo,
          action,
          matched_product_id: existing?.id || null,
          raw: row,
          before_state: existing ? { updated_at: existing.updated_at || null } : {},
          payload: normalized,
          barcode: normalized.barcode,
          requires_identical_confirmation: requiresIdenticalConfirmation,
        });

        if (action === 'create') creates += 1;
        if (action === 'update') updates += 1;
        if (requiresIdenticalConfirmation) {
          needsConfirmation += 1;
        }
        preview.push({
          row: rowNo,
          action,
          status: requiresIdenticalConfirmation ? 'needs_confirmation' : 'ready',
          errors: [],
          warnings,
          matched_product_id: existing?.id || null,
        });
      }

      if (!normalizedRows.length) {
        return res.status(400).json({
          error: 'No valid rows found in import file',
          preview,
        });
      }

      const batchId = crypto.randomUUID();
      const checksum = createImportBatchChecksum(normalizedRows, mode, stockMode);
      const createdAt = Date.now();
      const expiresAt = createdAt + PRODUCT_IMPORT_BATCH_TTL_MS;

      const batchPayload = {
        mode,
        stockMode,
        fileName: String(req.body?.file_name || '').trim(),
        rows: normalizedRows,
        createdBy: req.authUser?.id || null,
        createdAt,
        expiresAt,
      };
      productImportBatches.set(batchId, {
        ...batchPayload,
        checksum,
      });
      await dbRunAsync(SQL_UPSERT_IMPORT_BATCH, [
        batchId,
        'products',
        req.authUser?.id || null,
        JSON.stringify(batchPayload),
        checksum,
        errors ? 'staged_with_errors' : 'staged',
        expiresAt,
      ]);

      const responsePayload = {
        batch_id: batchId,
        checksum,
        expires_at: new Date(expiresAt).toISOString(),
        summary: {
          creates,
          updates,
          skips,
          errors,
          needs_confirmation: needsConfirmation,
        },
        preview,
      };

      if (Boolean(req.body?.auto_confirm)) {
        const jobResult = await queueImportBulkJobFromBatchAsync({
          catalogBulkJobs,
          req,
          batchId,
          checksum,
          batch: batchPayload,
          authUser: req.authUser,
          allowIdenticalRows: req.body?.allow_identical_rows || [],
        });
        responsePayload.auto_confirmed = true;
        responsePayload.job = jobResult.job;
        responsePayload.notification = {
          type: 'success',
          title: 'Product import queued',
          message: `Import job queued with ${batchPayload.rows.length} rows`,
        };
      }

      return res.json(responsePayload);
    } catch (error) {
      return res.status(error.status || 400).json({ error: error.message });
    }
  });
};

module.exports = { registerProductImportPreviewRoutes };

const createCommerceNotificationUtils = (deps = {}) => {
  const {
    dbGetAsync,
    dbAllAsync,
    normalizeTransactionDate,
    normalizePoPaymentStatus,
    PO_PAYMENT_UNPAID,
    createNotificationEvent,
    updateNotificationEventStatus,
    notificationService,
    whatsappProvider,
    WHATSAPP_DELIVERY_MODE,
    getDistributorWhatsappPhone,
  } = deps;

  const normalizeWhatsAppRecipientPhone = (phone) => {
    const digits = String(phone || '').replace(/\D/g, '');
    if (!digits) return '';
    if (digits.length === 10) return `91${digits}`;
    if (digits.length === 12 && digits.startsWith('91')) return digits;
    return digits;
  };

  const getRequestedDeliveryMode = () =>
    String(WHATSAPP_DELIVERY_MODE || 'manual')
      .trim()
      .toLowerCase() === 'auto'
      ? 'auto'
      : 'manual';

  const canAutoDeliverWhatsApp = () =>
    getRequestedDeliveryMode() === 'auto' &&
    Boolean(whatsappProvider?.supportsSend) &&
    Boolean(whatsappProvider?.isReady);

  const notifyDistributorPurchaseOrderAsync = async ({
    purchaseOrderId = null,
    distributorId,
    poNumber,
    totalAmount,
    paymentStatus = PO_PAYMENT_UNPAID,
    balanceDue = 0,
    expectedDelivery = null,
    notes = '',
    billNumber = '',
    isUpdate = false,
    items = [],
    messageDate = null,
    title = '',
    preparedBy = null,
  } = {}) => {
    const normalizedDistributorId = Number(distributorId || 0);
    if (!normalizedDistributorId) return { queued: false, reason: 'missing_distributor' };
    const distributor = await dbGetAsync(
      `SELECT id, name, contacts FROM distributors WHERE id = ?`,
      [normalizedDistributorId]
    );
    if (!distributor) return { queued: false, reason: 'distributor_not_found' };
    const normalizedPhone = getDistributorWhatsappPhone(distributor);
    if (!normalizedPhone) return { queued: false, reason: 'missing_phone' };

    const recipientPhone = normalizeWhatsAppRecipientPhone(normalizedPhone);
    if (!recipientPhone) return { queued: false, reason: 'invalid_phone' };

    const normalizedPurchaseOrderId = Number(purchaseOrderId || 0);
    let noticeItems = Array.isArray(items) ? items : [];
    if (!noticeItems.length && normalizedPurchaseOrderId) {
      noticeItems = await dbAllAsync(
        `SELECT poi.product_id, poi.product_name, poi.quantity, poi.uom, poi.rate, poi.unit_price, p.price AS product_price
         FROM purchase_order_items poi
         LEFT JOIN products p ON p.id = poi.product_id
         WHERE poi.order_id = ?
         ORDER BY poi.id ASC`,
        [normalizedPurchaseOrderId]
      );
    }
    const noticeProductIds = [
      ...new Set(
        noticeItems
          .map((item) => Number(item?.product_id || 0))
          .filter((value) => Number.isInteger(value) && value > 0)
      ),
    ];
    if (noticeProductIds.length > 0) {
      const placeholders = noticeProductIds.map(() => '?').join(', ');
      const productRows = await dbAllAsync(
        `SELECT id, price
         FROM products
         WHERE id IN (${placeholders})`,
        noticeProductIds
      );
      const productPriceById = new Map(
        productRows.map((row) => [Number(row?.id || 0), Number(row?.price || 0)])
      );
      noticeItems = noticeItems.map((item) => {
        const productId = Number(item?.product_id || 0);
        const productPrice = productPriceById.get(productId);
        if (!Number.isFinite(productPrice) || productPrice <= 0) return item;
        return {
          ...item,
          price: productPrice,
          product_price: productPrice,
        };
      });
    }

    const orderDate =
      normalizeTransactionDate(messageDate) || new Date().toISOString().slice(0, 10);
    const preparedWhatsApp = notificationService.prepareWhatsApp({
      type: 'purchase_order_distributor_notice',
      to: recipientPhone,
      payload: {
        title: String(title || '').trim() || `Order for ${orderDate}`,
        order_date: orderDate,
        items: noticeItems,
      },
    });
    const text = preparedWhatsApp.text;
    const normalizedRecipientPhone = preparedWhatsApp.to;
    const whatsappUrl = preparedWhatsApp.whatsapp_url;
    const requestedDeliveryMode = getRequestedDeliveryMode();
    const effectiveDeliveryMode = canAutoDeliverWhatsApp() ? 'auto' : 'manual';

    const eventId = await createNotificationEvent({
      type: 'purchase_order_distributor_notice',
      channel: 'whatsapp',
      recipient: normalizedRecipientPhone,
      recipientUserId: null,
      subject: `PO ${isUpdate ? 'update' : 'register'} ${poNumber || ''}`.trim(),
      body: text,
      metadata: {
        mode: effectiveDeliveryMode,
        requested_mode: requestedDeliveryMode,
        provider_supports_send: Boolean(whatsappProvider?.supportsSend),
        po_number: poNumber || null,
        distributor_id: normalizedDistributorId,
        items_count: noticeItems.length,
        order_date: orderDate,
        title: String(title || '').trim() || `Order for ${orderDate}`,
        balance_due: Number(balanceDue || 0),
        payment_status: normalizePoPaymentStatus(paymentStatus, PO_PAYMENT_UNPAID),
        bill_number: billNumber || null,
        expected_delivery: expectedDelivery ? String(expectedDelivery).slice(0, 10) : null,
      },
      status: 'prepared',
      preparedBy,
    });

    if (effectiveDeliveryMode !== 'auto') {
      return {
        queued: false,
        reason: 'manual_send_required',
        mode: effectiveDeliveryMode,
        event_id: eventId,
        whatsapp: {
          to: normalizedRecipientPhone,
          text,
          whatsapp_url: whatsappUrl,
        },
      };
    }

    try {
      await whatsappProvider.sendMessage({ to: normalizedRecipientPhone, text });
      await updateNotificationEventStatus(eventId, { status: 'sent' });
      return {
        queued: true,
        mode: 'auto',
        event_id: eventId,
        whatsapp: { to: normalizedRecipientPhone, text, whatsapp_url: whatsappUrl },
      };
    } catch (error) {
      await updateNotificationEventStatus(eventId, {
        status: 'failed',
        errorMessage: error?.message || String(error || 'WhatsApp send failed'),
      });
      return {
        queued: false,
        reason: 'send_failed',
        event_id: eventId,
        error: error?.message || String(error || 'WhatsApp send failed'),
        whatsapp: { to: normalizedRecipientPhone, text, whatsapp_url: whatsappUrl },
      };
    }
  };

  return { notifyDistributorPurchaseOrderAsync };
};

module.exports = { createCommerceNotificationUtils };

const applyConfirmStockAdjustments = async (deps, { req, order, stockAlreadyApplied }) => {
  const {
    dbAllAsync,
    dbGetAsync,
    dbRunAsync,
    logStockLedgerAsync,
    toPurchaseBaseQty,
    PURCHASE_STOCK_CAP,
  } = deps;

  const capAdjustments = [];
  if (stockAlreadyApplied) {
    return { capAdjustments };
  }

  const items = await dbAllAsync('SELECT * FROM purchase_order_items WHERE order_id = ?', [
    req.params.id,
  ]);
  for (const item of items) {
    const productId = Number(item.product_id || 0);
    if (!productId) continue;
    const product = await dbGetAsync(
      'SELECT id, stock, uom, base_unit, conversion_factor FROM products WHERE id = ?',
      [productId]
    );
    if (!product) continue;

    const orderedQtyInput = Math.max(0, Number(item.quantity || 0));
    const orderedQty = toPurchaseBaseQty(orderedQtyInput, item.uom, product);
    const beforeStock = Number(product.stock || 0);
    const intendedStock = beforeStock + orderedQty;
    const finalStock = Math.min(PURCHASE_STOCK_CAP, Math.max(0, intendedStock));
    const quantityChange = finalStock - beforeStock;
    const capHit = intendedStock > PURCHASE_STOCK_CAP || beforeStock > PURCHASE_STOCK_CAP;

    if (quantityChange !== 0) {
      await dbRunAsync('UPDATE products SET stock = ? WHERE id = ?', [finalStock, productId]);
      const noteLines = ['Auto stock update on PO confirmation'];
      if (capHit) {
        noteLines.push(
          `Stock cap ${PURCHASE_STOCK_CAP} applied (intended ${intendedStock}, final ${finalStock})`
        );
      }
      await logStockLedgerAsync({
        productId,
        transactionType: quantityChange >= 0 ? 'PURCHASE' : 'ADJUSTMENT',
        quantityChange,
        previousBalance: beforeStock,
        newBalance: finalStock,
        referenceType: 'PO_CONFIRM',
        referenceId: String(req.params.id),
        userId: req.body?.updated_by || req.body?.created_by || null,
        notes: noteLines.join('. '),
      });
    }

    if (capHit) {
      capAdjustments.push({
        product_id: productId,
        product_name: item.product_name || null,
        ordered_quantity: orderedQtyInput,
        ordered_quantity_base: orderedQty,
        before_stock: beforeStock,
        intended_stock: intendedStock,
        final_stock: finalStock,
        discarded_quantity: Math.max(0, intendedStock - finalStock),
        discarded_quantity_base: Math.max(0, intendedStock - finalStock),
      });
    }
  }

  return { capAdjustments };
};

module.exports = { applyConfirmStockAdjustments };

const updatePurchaseOrderWithItems = async (
  deps,
  {
    req,
    cur,
    items,
    updatedDistributorId,
    updatedSupplierId,
    updatedNotes,
    updatedExpectedDelivery,
    plannedOrderDate,
    paymentDueDate,
    strictDueDate,
    strictDueNote,
    currentPoStatus,
    nextLifecycleStatus,
    shouldIncrementRevision,
  }
) => {
  const {
    dbAllAsync,
    dbGetAsync,
    dbRunAsync,
    dbTxAsync,
    acquirePurchaseDuplicateLockAsync,
    buildPurchaseDuplicateKey,
    buildPurchaseTransactionTimestamp,
    calculatePoPaymentSnapshot,
    createPurchaseConflictError,
    findDuplicatePurchaseOrderAsync,
    normalizePurchaseOrderItems,
    recordProductCostHistoryEntryAsync,
    recordPurchaseOrderStatusHistoryAsync,
    syncDistributorProductsSuppliedAsync,
    upsertSupplierProductsAsync,
    derivePurchaseNextAction,
    PO_LIFECYCLE_SENT,
    PO_LIFECYCLE_REVISED,
  } = deps;

  if (!items.length) {
    const error = new Error('At least one item is required');
    error.status = 400;
    throw error;
  }

  const normalizedItems = await normalizePurchaseOrderItems(items);
  const duplicateKey = buildPurchaseDuplicateKey({
    distributorId: updatedDistributorId,
    plannedOrderDate,
    items: normalizedItems,
  });
  const subtotal = normalizedItems.reduce((sum, it) => sum + Number(it.taxable_value || 0), 0);
  const taxAmount = normalizedItems.reduce((sum, it) => sum + Number(it.tax_amount || 0), 0);
  const totalAmount = normalizedItems.reduce((sum, it) => sum + Number(it.line_total || 0), 0);
  const paymentSnapshot = calculatePoPaymentSnapshot(totalAmount, Number(cur.paid_amount || 0));

  await dbTxAsync(async () => {
    await acquirePurchaseDuplicateLockAsync({
      distributorId: updatedDistributorId,
      plannedOrderDate,
      duplicateKey,
    });
    const existingDuplicate = await findDuplicatePurchaseOrderAsync({
      distributorId: updatedDistributorId,
      plannedOrderDate,
      duplicateKey,
      excludeOrderId: Number(req.params.id || 0),
    });
    if (existingDuplicate) {
      throw createPurchaseConflictError(
        `Possible duplicate purchase order already exists (${existingDuplicate.po_number}) for the same distributor, planned date, and item basket`,
        'purchase_order_duplicate',
        existingDuplicate
      );
    }
    await dbRunAsync(
      `UPDATE purchase_orders
       SET distributor_id=?, supplier_id=?, notes=?, expected_delivery=?, planned_order_date=?, payment_due_date=?, strict_due_date=?, strict_due_note=?, duplicate_key=?, status=?, po_status=?, revision_count=?, next_action=?, subtotal=?, tax_amount=?, total_amount=?, total=?, payment_status=?, paid_amount=?, balance_due=?, updated_at=CURRENT_TIMESTAMP
       WHERE id=?`,
      [
        updatedDistributorId,
        updatedSupplierId || null,
        updatedNotes || null,
        updatedExpectedDelivery || null,
        plannedOrderDate,
        paymentDueDate,
        strictDueDate,
        strictDueNote,
        duplicateKey,
        nextLifecycleStatus === PO_LIFECYCLE_SENT ? 'sent' : 'pending',
        nextLifecycleStatus,
        shouldIncrementRevision
          ? Number(cur.revision_count || 0) + 1
          : Number(cur.revision_count || 0),
        nextLifecycleStatus === PO_LIFECYCLE_REVISED
          ? 'Resend updated PO'
          : derivePurchaseNextAction({ ...cur, po_status: nextLifecycleStatus }),
        subtotal,
        taxAmount,
        totalAmount,
        totalAmount,
        paymentSnapshot.paymentStatus,
        paymentSnapshot.paidAmount,
        paymentSnapshot.balanceDue,
        req.params.id,
      ]
    );
    await dbRunAsync('DELETE FROM product_cost_history WHERE po_id = ?', [req.params.id]);
    await dbRunAsync('DELETE FROM purchase_order_items WHERE order_id = ?', [req.params.id]);
    const transactionTs = buildPurchaseTransactionTimestamp(plannedOrderDate, new Date());
    for (const it of normalizedItems) {
      const insert = await dbRunAsync(
        `INSERT INTO purchase_order_items (order_id, product_id, product_name, row_source, quantity, received_quantity, uom, unit_price, rate, unit_price_before_discount, unit_discount_amount, tax_rate, unit_tax_amount, unit_cost_incl_tax, line_total_incl_tax, gst_rate, discount_type, discount_value, taxable_value, tax_amount, line_total, total)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          req.params.id,
          it.product_id || null,
          it.product_name || 'Unknown',
          it.row_source || 'manual',
          Number(it.quantity || 0),
          Number(it.received_quantity || 0),
          it.uom || 'pcs',
          Number(it.unit_price || 0),
          Number(it.rate || it.unit_price || 0),
          Number(it.unit_price_before_discount || 0),
          Number(it.unit_discount_amount || 0),
          Number(it.tax_rate || it.gst_rate || 0),
          Number(it.unit_tax_amount || 0),
          Number(it.unit_cost_incl_tax || 0),
          Number(it.line_total_incl_tax || it.line_total || 0),
          Number(it.gst_rate || 0),
          it.discount_type || 'percent',
          Number(it.discount_value || 0),
          Number(it.taxable_value || 0),
          Number(it.tax_amount || 0),
          Number(it.line_total || 0),
          Number(it.line_total || 0),
        ]
      );
      const poItemId = Number(insert?.lastInsertRowid || 0) || null;
      if (it.product_id && poItemId) {
        await recordProductCostHistoryEntryAsync({
          productId: it.product_id,
          distributorId: updatedDistributorId,
          purchaseOrderId: Number(req.params.id || 0),
          purchaseOrderItemId: poItemId,
          unitCostInclTax: it.unit_cost_incl_tax,
          taxRate: it.tax_rate || it.gst_rate,
          discountAmount: it.unit_discount_amount,
          transactionTs,
        });
      }
    }
    await upsertSupplierProductsAsync(updatedDistributorId, normalizedItems, {
      supplierId: updatedSupplierId || null,
    });
  });

  await syncDistributorProductsSuppliedAsync(updatedDistributorId, normalizedItems, {
    supplierId: updatedSupplierId || null,
  });
  if (nextLifecycleStatus !== currentPoStatus) {
    await recordPurchaseOrderStatusHistoryAsync(req.params.id, {
      fromStatus: currentPoStatus,
      toStatus: nextLifecycleStatus,
      note: 'Purchase order revised after edits',
      paymentStatus: paymentSnapshot.paymentStatus,
      balanceDue: paymentSnapshot.balanceDue,
      createdBy: req?.authUser?.id || req.body?.created_by || null,
    });
  }

  return { paymentSnapshot };
};

module.exports = { updatePurchaseOrderWithItems };

const { resolvePurchaseOrderIdempotency } = require('./listCreate/resolveIdempotency');
const { validatePurchaseOrderInput } = require('./listCreate/validateInput');
const { buildPurchaseOrderContext } = require('./listCreate/buildContext');
const { createPurchaseOrderTransaction } = require('./listCreate/createTransaction');
const { logPurchaseOrderCreateAudit } = require('./listCreate/logAudit');

const registerPurchaseOrdersListCreateRoutes = (deps) => {
  const {
    app,
    requireAdmin,
    dbAllAsync,
    dbGetAsync,
    dbRunAsync,
    dbTxAsync,
    acquirePurchaseDuplicateLockAsync,
    buildPurchaseDuplicateKey,
    buildPurchaseTransactionTimestamp,
    calculatePoPaymentSnapshot,
    computePurchasePaymentDueDate,
    createPurchaseConflictError,
    findDuplicatePurchaseOrderAsync,
    generatePONumber,
    getDistributorByIdAsync,
    getSupplierByIdAsync,
    isUniqueViolationError,
    logAdminAuditAsync,
    normalizePurchaseOrderItems,
    normalizeTransactionDate,
    recordProductCostHistoryEntryAsync,
    recordPurchaseOrderStatusHistoryAsync,
    resolveClientRequestId,
    syncDistributorProductsSuppliedAsync,
    upsertSupplierProductsAsync,
    PO_LIFECYCLE_PREPARED,
  } = deps;

  app.post('/api/purchase-orders', requireAdmin, async (req, res) => {
    let clientRequestId = null;
    try {
      const b = req.body || {};
      const idempotency = await resolvePurchaseOrderIdempotency({
        req,
        resolveClientRequestId,
        dbGetAsync,
      });
      if (idempotency.error) return res.status(400).json({ error: idempotency.error });
      clientRequestId = idempotency.clientRequestId;
      if (idempotency.existing) {
        return res.status(200).json({
          success: true,
          deduplicated: true,
          id: Number(idempotency.existing.id),
          po_number: idempotency.existing.po_number,
        });
      }

      const { distributor, supplier, distributorId, supplierId, normalizedItems } =
        await validatePurchaseOrderInput({
          body: b,
          getDistributorByIdAsync,
          getSupplierByIdAsync,
          normalizePurchaseOrderItems,
        });

      const context = buildPurchaseOrderContext({
        body: {
          ...b,
          distributor_id: distributorId,
          supplier_id: supplierId || b.supplier_id || null,
        },
        distributor,
        normalizedItems,
        buildPurchaseDuplicateKey,
        normalizeTransactionDate,
        calculatePoPaymentSnapshot,
        computePurchasePaymentDueDate,
      });

      const poNumber = generatePONumber();
      const { orderId } = await createPurchaseOrderTransaction({
        body: {
          ...b,
          distributor_id: distributorId,
          supplier_id: supplierId || b.supplier_id || null,
        },
        poNumber,
        clientRequestId,
        context,
        normalizedItems,
        acquirePurchaseDuplicateLockAsync,
        findDuplicatePurchaseOrderAsync,
        createPurchaseConflictError,
        dbTxAsync,
        dbRunAsync,
        dbGetAsync,
        buildPurchaseTransactionTimestamp,
        recordProductCostHistoryEntryAsync,
        upsertSupplierProductsAsync,
        recordPurchaseOrderStatusHistoryAsync,
        PO_LIFECYCLE_PREPARED,
      });

      await syncDistributorProductsSuppliedAsync(Number(distributorId || 0), normalizedItems, {
        supplierId: supplierId || b.supplier_id || null,
      });
      await logPurchaseOrderCreateAudit({
        req,
        logAdminAuditAsync,
        clientRequestId,
        orderId,
        poNumber,
        totalAmount: context.totalAmount,
        normalizedItems,
        distributorId,
      });
      return res.status(201).json({
        success: true,
        id: orderId,
        po_number: poNumber,
        po_status: PO_LIFECYCLE_PREPARED,
        payment_status: context.paymentSnapshot.paymentStatus,
        paid_amount: context.paymentSnapshot.paidAmount,
        balance_due: context.paymentSnapshot.balanceDue,
        payment_due_date: context.paymentDueDate,
        strict_due_date: context.strictDueDate,
      });
    } catch (error) {
      if (clientRequestId && isUniqueViolationError(error)) {
        const existing = await dbGetAsync(
          'SELECT id, po_number FROM purchase_orders WHERE client_request_id = ? LIMIT 1',
          [clientRequestId]
        );
        if (existing) {
          return res.status(200).json({
            success: true,
            deduplicated: true,
            id: Number(existing.id),
            po_number: existing.po_number,
          });
        }
      }
      if (error.status === 400) {
        return res.status(400).json({ error: error.message, details: error.details || undefined });
      }
      if (error.status === 404) {
        return res.status(404).json({ error: error.message });
      }
      if (error.status === 409) {
        return res.status(409).json({
          error: error.message,
          conflict_type: error.conflictType || undefined,
          conflict: error.conflict || undefined,
        });
      }
      return res.status(500).json({ error: error.message });
    }
  });
};

module.exports = { registerPurchaseOrdersListCreateRoutes };

const finalizePurchaseOrderReceive = async (deps, { req, order, poStatus, nextAction }) => {
  const {
    dbGetAsync,
    dbRunAsync,
    calculatePoPaymentSnapshot,
    derivePoLifecycleFromPaymentStatus,
    derivePurchaseNextAction,
  } = deps;

  const totals = await dbGetAsync(
    `SELECT
       COALESCE(SUM(taxable_value), 0) AS subtotal,
       COALESCE(SUM(tax_amount), 0) AS tax_amount,
       COALESCE(SUM(line_total), 0) AS total_amount
     FROM purchase_order_items
     WHERE order_id = ?`,
    [req.params.id]
  );
  const receivePaymentSnapshot = calculatePoPaymentSnapshot(
    Number(totals?.total_amount || 0),
    Number(order.paid_amount || 0)
  );
  const nextLifecycleStatus = derivePoLifecycleFromPaymentStatus(
    poStatus,
    receivePaymentSnapshot.paymentStatus
  );
  const nextActionResolved = derivePurchaseNextAction({
    ...order,
    status: 'received',
    received_at: new Date().toISOString(),
    po_status: nextLifecycleStatus,
    payment_status: receivePaymentSnapshot.paymentStatus,
    balance_due: receivePaymentSnapshot.balanceDue,
  });

  await dbRunAsync(
    `UPDATE purchase_orders
     SET status = 'received',
         po_status = ?,
         invoice_number = ?,
         subtotal = ?,
         tax_amount = ?,
         total_amount = ?,
         total = ?,
         payment_status = ?,
         paid_amount = ?,
         balance_due = ?,
         received_at = COALESCE(received_at, CURRENT_TIMESTAMP),
         next_action = ?,
         updated_at = CURRENT_TIMESTAMP
     WHERE id = ?`,
    [
      nextLifecycleStatus,
      req.body?.invoice_number || order.invoice_number || null,
      Number(totals?.subtotal || 0),
      Number(totals?.tax_amount || 0),
      Number(totals?.total_amount || 0),
      Number(totals?.total_amount || 0),
      receivePaymentSnapshot.paymentStatus,
      receivePaymentSnapshot.paidAmount,
      receivePaymentSnapshot.balanceDue,
      nextActionResolved,
      req.params.id,
    ]
  );

  return {
    nextLifecycleStatus,
    nextAction: nextActionResolved,
    receivePaymentSnapshot,
  };
};

module.exports = { finalizePurchaseOrderReceive };

const registerPurchaseReturnsCreateRoutes = (deps) => {
  const {
    app,
    requireAdmin,
    dbAllAsync,
    dbGetAsync,
    dbRunAsync,
    dbTxAsync,
    logStockLedgerAsync,
    generateReturnNumber,
    getAllowedPurchaseUnitsForProductRow,
    getPurchaseProductUomProfile,
    normalizePurchaseUomToken,
    toPurchaseBaseQty,
  } = deps;

  app.post('/api/purchase-returns', requireAdmin, async (req, res) => {
    try {
      const b = req.body || {};
      const items = Array.isArray(b.items) ? b.items : [];
      if (!b.distributor_id) return res.status(400).json({ error: 'distributor_id is required' });
      if (!items.length) return res.status(400).json({ error: 'At least one item is required' });
      const productCache = new Map();
      const itemErrors = [];
      const normalizedItems = [];
      for (let index = 0; index < items.length; index += 1) {
        const rowNo = index + 1;
        const it = items[index] || {};
        const productId = Number(it.product_id || 0) || 0;
        if (!productId) {
          itemErrors.push(`Item ${rowNo}: product_id is required`);
          continue;
        }
        if (!productCache.has(productId)) {
          const product = await dbGetAsync(
            'SELECT id, name, uom, base_unit, conversion_factor FROM products WHERE id = ?',
            [productId]
          );
          productCache.set(productId, product || null);
        }
        const product = productCache.get(productId);
        if (!product) {
          itemErrors.push(`Item ${rowNo}: product ${productId} not found`);
          continue;
        }
        const quantity = Math.max(0, Number(it.quantity || 0));
        if (quantity <= 0) {
          itemErrors.push(`Item ${rowNo}: quantity must be greater than 0`);
          continue;
        }
        const providedUomRaw = String(it.uom || '').trim();
        const allowedUnits = getAllowedPurchaseUnitsForProductRow(product);
        let normalizedUom = allowedUnits[0] || getPurchaseProductUomProfile(product).baseUnit;
        if (providedUomRaw) {
          const requestedUom = normalizePurchaseUomToken(providedUomRaw, normalizedUom);
          if (!allowedUnits.includes(requestedUom)) {
            itemErrors.push(
              `Item ${rowNo}: unit "${providedUomRaw}" is invalid for product ${product.id}. Allowed: ${allowedUnits.join(', ')}`
            );
            continue;
          }
          normalizedUom = requestedUom;
        }
        const quantityBase = toPurchaseBaseQty(quantity, normalizedUom, product);
        const unitPrice = Math.max(0, Number(it.unit_price || 0));
        normalizedItems.push({
          product_id: productId,
          product_name:
            String(it.product_name || '').trim() || String(product.name || '').trim() || 'Unknown',
          quantity,
          quantity_base: quantityBase,
          uom: normalizedUom,
          unit_price: unitPrice,
          total: quantityBase * unitPrice,
          reason: it.reason || b.reason || null,
        });
      }

      if (itemErrors.length) {
        return res
          .status(400)
          .json({ error: 'Invalid purchase return items', details: itemErrors });
      }

      const total = normalizedItems.reduce((sum, it) => sum + Number(it.total || 0), 0);
      const returnNumber = generateReturnNumber();
      const returnId = await dbTxAsync(async () => {
        const head = await dbRunAsync(
          `INSERT INTO purchase_returns (return_number, distributor_id, total, reason, return_type, reference_po, created_by)
           VALUES (?, ?, ?, ?, ?, ?, ?)`,
          [
            returnNumber,
            b.distributor_id,
            total,
            b.reason || null,
            b.return_type || 'return',
            b.reference_po || null,
            b.created_by || null,
          ]
        );
        const returnId = head.lastInsertRowid;
        for (const it of normalizedItems) {
          await dbRunAsync(
            `INSERT INTO purchase_return_items (return_id, product_id, product_name, quantity, uom, unit_price, total, reason)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
            [
              returnId,
              it.product_id || null,
              it.product_name || 'Unknown',
              Number(it.quantity || 0),
              it.uom || 'pcs',
              Number(it.unit_price || 0),
              Number(it.total || 0),
              it.reason || b.reason || null,
            ]
          );
          if (it.product_id) {
            const before =
              (await dbGetAsync('SELECT stock FROM products WHERE id = ?', [it.product_id]))
                ?.stock || 0;
            await dbRunAsync('UPDATE products SET stock = stock - ? WHERE id = ?', [
              Number(it.quantity_base || 0),
              it.product_id,
            ]);
            const after =
              (await dbGetAsync('SELECT stock FROM products WHERE id = ?', [it.product_id]))
                ?.stock || 0;
            await logStockLedgerAsync({
              productId: it.product_id,
              transactionType: 'PURCHASE_RETURN',
              quantityChange: -Number(it.quantity_base || 0),
              previousBalance: before,
              newBalance: after,
              referenceType: 'PURCHASE_RETURN',
              referenceId: String(returnId),
              userId: b.created_by || null,
            });
          }
        }
        return returnId;
      });
      return res.status(201).json({ success: true, id: returnId, return_number: returnNumber });
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });
};

