const {
  SCORE_BANDS,
  DEFAULT_GRACE_DAYS,
  DEFAULT_NEW_STATUS_DAYS,
  NEW_CUSTOMER_STATUS,
  getBandIndex,
  getBandScoreForElapsedDays,
  getCycleBandForElapsedDays,
  getFirstEstablishedBand,
  getNextBetterBand,
} = require('./creditStatusPolicy');

const CREDIT_BADGE_SETTINGS = {
  paymentWindow30Days: 30,
  paymentWindow60Days: 60,
  paymentWindow90Days: 90,
  defaultGraceDays: DEFAULT_GRACE_DAYS,
  minEstablishedPeriods: 1,
};

const PAYMENT_DAY_MS = 24 * 60 * 60 * 1000;
const EPSILON = 0.000001;
const LEGACY_GRACE_DAYS = 60;

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

const toFiniteNumber = (value, fallback = 0) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const roundMoney = (value) => {
  const numeric = toFiniteNumber(value, 0);
  return Math.round(numeric * 100) / 100;
};

const roundRatio = (value) => {
  if (!Number.isFinite(value)) return 0;
  return Math.round(value * 1000) / 1000;
};

const getUtcMonthKey = (timestampMs) => {
  const date = new Date(timestampMs);
  if (Number.isNaN(date.getTime())) return '';
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  return `${year}-${month}`;
};

const getUtcDateKey = (timestampMs) => {
  const date = new Date(timestampMs);
  if (Number.isNaN(date.getTime())) return '';
  return date.toISOString().slice(0, 10);
};

const formatPaymentBadgeDate = (timestampMs) => {
  if (!Number.isFinite(timestampMs) || timestampMs <= 0) return '';
  return new Date(timestampMs).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' });
};

const toAgeDays = (endMs, startMs) => {
  if (!Number.isFinite(endMs) || !Number.isFinite(startMs) || endMs <= 0 || startMs <= 0) return 0;
  return Math.max(0, Math.floor((endMs - startMs) / PAYMENT_DAY_MS));
};

const getOutstandingTone = (days) => {
  const ageDays = Math.max(0, Math.round(toFiniteNumber(days, 0)));
  if (ageDays <= 7) return 'very-good';
  if (ageDays <= 30) return 'good';
  if (ageDays <= 60) return 'attention';
  return 'problem';
};

const dateKeyToUtcMs = (dateKey) => {
  const normalized = String(dateKey || '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized)) return 0;
  return Date.parse(`${normalized}T00:00:00.000Z`);
};

const addDaysToDateKey = (dateKey, days) => {
  const baseMs = dateKeyToUtcMs(dateKey);
  if (!baseMs) return '';
  return getUtcDateKey(baseMs + Math.max(0, Math.floor(toFiniteNumber(days, 0))) * PAYMENT_DAY_MS);
};

const diffDateKeysInDays = (laterDateKey, earlierDateKey) => {
  const laterMs = dateKeyToUtcMs(laterDateKey);
  const earlierMs = dateKeyToUtcMs(earlierDateKey);
  if (!laterMs || !earlierMs) return 0;
  return Math.round((laterMs - earlierMs) / PAYMENT_DAY_MS);
};

const toIsoOrNull = (timestampMs) => {
  if (!Number.isFinite(timestampMs) || timestampMs <= 0) return null;
  return new Date(timestampMs).toISOString();
};

const normalizeGraceDays = (value) => {
  const parsed = Math.max(0, Math.floor(toFiniteNumber(value, DEFAULT_GRACE_DAYS)));
  if (parsed === LEGACY_GRACE_DAYS) return DEFAULT_GRACE_DAYS;
  return parsed || DEFAULT_GRACE_DAYS;
};

const buildStatusHelper = ({
  isNewCustomer,
  displayStatus,
  nextBetterBand,
  activeCycleStartDateKey,
  activeCycleDueDateKey,
  graceDays,
  nowDateKey,
  outstandingAmount,
} = {}) => {
  if (isNewCustomer) {
    return {
      mode: 'unlock',
      text: `Complete your first ${DEFAULT_NEW_STATUS_DAYS}-day cycle to unlock your payment status.`,
    };
  }

  if (!displayStatus) {
    return {
      mode: 'neutral',
      text: 'No payment status available yet.',
    };
  }

  if (
    !Number.isFinite(outstandingAmount) ||
    outstandingAmount <= EPSILON ||
    !activeCycleDueDateKey
  ) {
    return {
      mode: 'clear',
      text: 'No unpaid due right now. Keep clearing entries on time.',
    };
  }

  const dueDateKey = String(activeCycleDueDateKey || '').trim();
  const dueDateLabel = formatPaymentBadgeDate(dateKeyToUtcMs(dueDateKey));
  const graceEndDateKey = addDaysToDateKey(dueDateKey, graceDays);
  const graceEndLabel = formatPaymentBadgeDate(dateKeyToUtcMs(graceEndDateKey));
  const cycleStartLabel = formatPaymentBadgeDate(dateKeyToUtcMs(activeCycleStartDateKey));

  if (graceEndDateKey && nowDateKey > graceEndDateKey) {
    return {
      mode: 'missed',
      text: `This cycle started on ${cycleStartLabel || dueDateLabel}. Grace ended on ${graceEndLabel || dueDateLabel}; pay now to avoid another downgrade.`,
    };
  }

  if (dueDateKey && nowDateKey > dueDateKey) {
    return {
      mode: 'overdue',
      text: `Current due date passed. Pay by ${graceEndLabel || dueDateLabel} to avoid another downgrade.`,
    };
  }

  if (
    String(displayStatus.key || '')
      .trim()
      .toLowerCase() === 'excellent'
  ) {
    return {
      mode: 'maintain',
      text: `Pay by ${dueDateLabel} to keep Excellent.`,
    };
  }

  return {
    mode: 'improve',
    text: `Current cycle is ${displayStatus.label}. Pay by ${dueDateLabel} to avoid another downgrade and work back toward ${nextBetterBand?.label || 'a better status'}.`,
  };
};

const buildCycleState = (startDateKey, referenceDateKey, graceDays = DEFAULT_GRACE_DAYS) => {
  const normalizedStartDateKey = String(startDateKey || '').trim();
  const normalizedReferenceDateKey = String(referenceDateKey || '').trim();
  if (!normalizedStartDateKey || !normalizedReferenceDateKey) {
    return {
      band: null,
      elapsedDays: 0,
      dueDateKey: '',
      graceEndDateKey: '',
      overdueDays: 0,
      earlyDays: 0,
      isPastDue: false,
      isAfterGrace: false,
      score: null,
    };
  }

  const elapsedDays = Math.max(
    0,
    diffDateKeysInDays(normalizedReferenceDateKey, normalizedStartDateKey)
  );
  const band = getCycleBandForElapsedDays(elapsedDays, { graceDays }) || getFirstEstablishedBand();
  const dueDateKey = band
    ? addDaysToDateKey(normalizedStartDateKey, Number(band.target_days || 0))
    : '';
  const graceEndDateKey = dueDateKey ? addDaysToDateKey(dueDateKey, graceDays) : '';
  const overdueDays = dueDateKey
    ? Math.max(0, diffDateKeysInDays(normalizedReferenceDateKey, dueDateKey))
    : 0;
  const earlyDays = dueDateKey
    ? Math.max(0, diffDateKeysInDays(dueDateKey, normalizedReferenceDateKey))
    : 0;
  const isPastDue = Boolean(dueDateKey) && normalizedReferenceDateKey > dueDateKey;
  const isAfterGrace = Boolean(graceEndDateKey) && normalizedReferenceDateKey > graceEndDateKey;
  const score = band ? getBandScoreForElapsedDays(band.key, elapsedDays, { graceDays }) : null;

  return {
    band,
    elapsedDays,
    dueDateKey,
    graceEndDateKey,
    overdueDays,
    earlyDays,
    isPastDue,
    isAfterGrace,
    score,
  };
};

const classifySettledCycle = ({ earlyDays = 0, overdueDays = 0, isAfterGrace = false } = {}) => {
  if (isAfterGrace) {
    return {
      bucket: 'late_after_grace',
      delta: -15,
      label: 'Paid after grace period',
    };
  }

  if (earlyDays >= 7) {
    return {
      bucket: 'early_7_plus',
      delta: 5,
      label: 'Paid 7+ days early',
    };
  }

  if (earlyDays >= 3) {
    return {
      bucket: 'early_3_to_6',
      delta: 3,
      label: 'Paid 3-6 days early',
    };
  }

  if (earlyDays >= 1) {
    return {
      bucket: 'early_1_to_2',
      delta: 1,
      label: 'Paid 1-2 days early',
    };
  }

  if (overdueDays > 0) {
    return {
      bucket: 'late_within_grace',
      delta: -3,
      label: 'Paid after due date',
    };
  }

  return {
    bucket: 'on_due_date',
    delta: 0,
    label: 'Paid on due date',
  };
};

const createCreditBadgeUtils = ({ resolveCreditEntryTimestampMs } = {}) => {
  const buildCreditDisciplineProfile = (
    entries,
    {
      balance = 0,
      creditLimit = 0,
      nowMs = Date.now(),
      isActive = true,
      graceDays = CREDIT_BADGE_SETTINGS.defaultGraceDays,
    } = {}
  ) => {
    const normalizedGraceDays = normalizeGraceDays(graceDays);
    const normalizedIsActive = Boolean(isActive);
    const nowDateKey = getUtcDateKey(nowMs);
    const nowDateMs = dateKeyToUtcMs(nowDateKey);

    const normalizedRows = (Array.isArray(entries) ? entries : [])
      .map((entry, index) => {
        const timestampMs = resolveCreditEntryTimestampMs(entry);
        const createdAtMs = Date.parse(String(entry?.created_at || '').trim() || 0);
        const amount = Math.abs(toFiniteNumber(entry?.amount, 0));
        const type = String(entry?.type || '')
          .trim()
          .toLowerCase();
        if (!Number.isFinite(timestampMs) || timestampMs <= 0) return null;
        if (amount <= 0) return null;
        if (type !== 'given' && type !== 'payment') return null;
        const rawDueDate = String(entry?.due_date || entry?.dueDate || '').trim();
        const dueDateKey = /^\d{4}-\d{2}-\d{2}$/.test(rawDueDate)
          ? rawDueDate
          : getUtcDateKey(timestampMs);
        const rawTransactionDate = String(entry?.transaction_date || '').trim();
        const transactionDateKey = /^\d{4}-\d{2}-\d{2}$/.test(rawTransactionDate)
          ? rawTransactionDate
          : getUtcDateKey(timestampMs);
        return {
          id: Number(entry?.id || 0) || null,
          index,
          type,
          amount,
          timestampMs,
          createdAtMs: Number.isFinite(createdAtMs) ? createdAtMs : 0,
          createdAt: entry?.created_at || null,
          transactionDateKey,
          dueDateKey,
          sourceType: String(entry?.source_type || '')
            .trim()
            .toLowerCase(),
          sourceId: String(entry?.source_id || '').trim(),
          sourceLabel: String(entry?.source_label || entry?.reference || '').trim(),
          reference: String(entry?.reference || '').trim(),
        };
      })
      .filter(Boolean)
      .sort(
        (a, b) =>
          a.timestampMs - b.timestampMs ||
          a.createdAtMs - b.createdAtMs ||
          (a.id || 0) - (b.id || 0) ||
          a.index - b.index
      );

    const paymentTimeline = [];
    const periods = [];

    for (const row of normalizedRows) {
      if (row.type === 'payment') {
        paymentTimeline.push({
          id: row.id,
          amount: row.amount,
          timestampMs: row.timestampMs,
          transactionDateKey: row.transactionDateKey,
        });
        continue;
      }

      periods.push({
        period_key: row.id ? `credit:${row.id}` : `credit:${row.index}:${row.timestampMs}`,
        source_credit_entry_id: row.id,
        period_start: toIsoOrNull(row.timestampMs),
        period_start_ms: row.timestampMs,
        period_start_date_key: row.transactionDateKey || getUtcDateKey(row.timestampMs),
        due_date: row.dueDateKey || row.transactionDateKey || getUtcDateKey(row.timestampMs),
        grace_days: normalizedGraceDays,
        expected_amount: roundMoney(row.amount),
        allocated_amount: 0,
        remaining_amount: roundMoney(row.amount),
        is_fully_settled: false,
        settled_at: null,
        source_type: row.sourceType || null,
        source_id: row.sourceId || (row.id ? String(row.id) : null),
        source_label: row.sourceLabel || row.reference || null,
      });
    }

    let unappliedPaymentAmount = 0;
    for (const payment of paymentTimeline) {
      let paymentRemaining = roundMoney(payment.amount);
      for (const period of periods) {
        if (paymentRemaining <= EPSILON) break;
        if (period.remaining_amount <= EPSILON) continue;
        const appliedAmount = Math.min(paymentRemaining, period.remaining_amount);
        period.allocated_amount = roundMoney(period.allocated_amount + appliedAmount);
        period.remaining_amount = roundMoney(period.remaining_amount - appliedAmount);
        if (period.remaining_amount <= EPSILON) {
          period.remaining_amount = 0;
          period.is_fully_settled = true;
          period.settled_at = toIsoOrNull(payment.timestampMs);
        }
        paymentRemaining = roundMoney(paymentRemaining - appliedAmount);
      }
      if (paymentRemaining > EPSILON) {
        unappliedPaymentAmount = roundMoney(unappliedPaymentAmount + paymentRemaining);
      }
    }

    const scoredPeriods = periods.map((period) => {
      const settledAtMs = period.settled_at ? Date.parse(period.settled_at) : 0;
      const settledDateKey = settledAtMs ? getUtcDateKey(settledAtMs) : '';
      const referenceDateKey = period.is_fully_settled ? settledDateKey : nowDateKey;
      const cycleState = buildCycleState(
        period.period_start_date_key,
        referenceDateKey,
        normalizedGraceDays
      );
      const ageDays = toAgeDays(nowMs, period.period_start_ms);

      let status = 'paid';
      let scoreBucket = 'open';
      let scoreDelta = 0;
      let scoreBucketLabel = period.is_fully_settled ? 'Paid' : 'Open';
      let judged = false;

      if (period.is_fully_settled) {
        const settledCycle = classifySettledCycle({
          earlyDays: cycleState.earlyDays,
          overdueDays: cycleState.overdueDays,
          isAfterGrace: cycleState.isAfterGrace,
        });
        status = 'paid';
        scoreBucket = settledCycle.bucket;
        scoreDelta = settledCycle.delta;
        scoreBucketLabel = settledCycle.label;
        judged = true;
      } else if (cycleState.isAfterGrace) {
        status = 'missed';
        scoreBucket = 'missed';
        scoreDelta = -15;
        scoreBucketLabel = 'Missed beyond grace';
        judged = true;
      } else if (cycleState.isPastDue) {
        status = 'late';
        scoreBucket = 'late';
        scoreBucketLabel = 'Past due';
      } else {
        status = 'pending';
        scoreBucket = 'open';
        scoreBucketLabel = 'Open';
      }

      return {
        ...period,
        settled_at_ms: settledAtMs || null,
        settled_date_key: settledDateKey || null,
        status,
        delay_days: cycleState.overdueDays,
        early_days: period.is_fully_settled ? cycleState.earlyDays : 0,
        age_days: ageDays,
        elapsed_days: cycleState.elapsedDays,
        grace_end_date: cycleState.graceEndDateKey,
        cycle_due_date: cycleState.dueDateKey,
        cycle_band: cycleState.band || null,
        cycle_band_key: cycleState.band?.key || null,
        cycle_band_label: cycleState.band?.label || null,
        cycle_band_tone: cycleState.band?.tone || null,
        cycle_score: cycleState.score,
        score_bucket: scoreBucket,
        score_delta: scoreDelta,
        score_bucket_label: scoreBucketLabel,
        judged,
        score_before: null,
        score_after: judged ? cycleState.score : null,
      };
    });

    const openPeriods = scoredPeriods.filter((period) => period.remaining_amount > EPSILON);
    const settledPeriods = scoredPeriods.filter((period) => period.is_fully_settled);
    const earliestOpenPeriod = openPeriods[0] || null;
    const lastSettledPeriod = settledPeriods.reduce((latest, period) => {
      if (!latest) return period;
      return Number(period.settled_at_ms || 0) > Number(latest.settled_at_ms || 0)
        ? period
        : latest;
    }, null);

    const firstEstablishedBand = getFirstEstablishedBand() || NEW_CUSTOMER_STATUS;
    const firstPeriodStartDateKey = String(scoredPeriods[0]?.period_start_date_key || '').trim();
    const firstCycleJudgementDateKey = firstPeriodStartDateKey
      ? addDaysToDateKey(
          addDaysToDateKey(
            firstPeriodStartDateKey,
            Number(firstEstablishedBand.target_days || DEFAULT_NEW_STATUS_DAYS)
          ),
          normalizedGraceDays
        )
      : '';

    const totalPeriods = scoredPeriods.length;
    const isNewCustomer =
      totalPeriods === 0 ||
      (!settledPeriods.length &&
        firstCycleJudgementDateKey &&
        nowDateKey <= firstCycleJudgementDateKey);

    let displayStatus = earliestOpenPeriod?.cycle_band || null;
    let paymentScore = earliestOpenPeriod?.cycle_score ?? null;
    let activeCycleStartDateKey = String(earliestOpenPeriod?.period_start_date_key || '').trim();
    let activeCycleDueDateKey = String(earliestOpenPeriod?.cycle_due_date || '').trim();

    if (!earliestOpenPeriod && lastSettledPeriod) {
      displayStatus = lastSettledPeriod.cycle_band || null;
      paymentScore = lastSettledPeriod.cycle_score ?? null;
      activeCycleStartDateKey = String(lastSettledPeriod.period_start_date_key || '').trim();
      activeCycleDueDateKey = '';
    }

    if (!displayStatus) {
      displayStatus = firstEstablishedBand || NEW_CUSTOMER_STATUS;
    }

    const activeCycleMisses =
      !isNewCustomer && earliestOpenPeriod?.cycle_band?.key
        ? Math.max(0, getBandIndex(earliestOpenPeriod.cycle_band.key))
        : 0;
    const judgedPeriods =
      settledPeriods.length + openPeriods.filter((period) => period.status === 'missed').length;
    const onTimePeriods = settledPeriods.filter((period) => period.delay_days <= 0).length;
    const within7Days = settledPeriods.filter(
      (period) => period.delay_days > 0 && period.delay_days <= 7
    ).length;
    const within30Days = settledPeriods.filter(
      (period) => period.delay_days > 7 && period.delay_days <= 30
    ).length;
    const within60Days = settledPeriods.filter(
      (period) => period.delay_days > 30 && period.delay_days <= 60
    ).length;
    const latePeriods =
      settledPeriods.filter((period) => period.delay_days > 0).length +
      (earliestOpenPeriod &&
      (earliestOpenPeriod.status === 'late' || earliestOpenPeriod.status === 'missed')
        ? 1
        : 0);
    const missedPeriods =
      settledPeriods.filter((period) => period.score_bucket === 'late_after_grace').length +
      activeCycleMisses;
    const totalDelayDays =
      settledPeriods.reduce(
        (sum, period) => sum + Math.max(0, toFiniteNumber(period.delay_days, 0)),
        0
      ) +
      openPeriods
        .filter((period) => period.status === 'missed')
        .reduce((sum, period) => sum + Math.max(0, toFiniteNumber(period.delay_days, 0)), 0);
    const averageDelayDays = judgedPeriods > 0 ? totalDelayDays / judgedPeriods : 0;
    const averageSettlementDays =
      settledPeriods.length > 0
        ? settledPeriods.reduce(
            (sum, period) => sum + Math.max(0, toFiniteNumber(period.elapsed_days, 0)),
            0
          ) / settledPeriods.length
        : null;
    const outstandingAmount = roundMoney(
      openPeriods.reduce((sum, period) => sum + toFiniteNumber(period.remaining_amount, 0), 0)
    );
    const oldestOpenDays = openPeriods.reduce(
      (maxAge, period) => (period.age_days > maxAge ? period.age_days : maxAge),
      0
    );
    const oldestOverdueDays =
      earliestOpenPeriod &&
      (earliestOpenPeriod.status === 'late' || earliestOpenPeriod.status === 'missed')
        ? Math.max(0, toFiniteNumber(earliestOpenPeriod.delay_days, 0))
        : 0;
    const aging0To30 = roundMoney(
      openPeriods.reduce(
        (sum, period) =>
          sum + (period.age_days <= 30 ? toFiniteNumber(period.remaining_amount, 0) : 0),
        0
      )
    );
    const aging31To60 = roundMoney(
      openPeriods.reduce(
        (sum, period) =>
          sum +
          (period.age_days > 30 && period.age_days <= 60
            ? toFiniteNumber(period.remaining_amount, 0)
            : 0),
        0
      )
    );
    const aging61To90 = roundMoney(
      openPeriods.reduce(
        (sum, period) =>
          sum +
          (period.age_days > 60 && period.age_days <= 90
            ? toFiniteNumber(period.remaining_amount, 0)
            : 0),
        0
      )
    );
    const agingOver90 = roundMoney(
      openPeriods.reduce(
        (sum, period) =>
          sum + (period.age_days > 90 ? toFiniteNumber(period.remaining_amount, 0) : 0),
        0
      )
    );

    const positivePoints = settledPeriods.reduce(
      (sum, period) => (period.score_delta > 0 ? sum + period.score_delta : sum),
      0
    );
    const latePenaltyPoints = settledPeriods.reduce(
      (sum, period) =>
        period.score_bucket === 'late_within_grace' ? sum + Math.abs(period.score_delta || 0) : sum,
      0
    );
    const missedPenaltyPoints =
      settledPeriods.reduce(
        (sum, period) =>
          period.score_bucket === 'late_after_grace'
            ? sum + Math.abs(period.score_delta || 0)
            : sum,
        0
      ) +
      activeCycleMisses * 3;
    const averageWeight =
      judgedPeriods > 0 ? (onTimePeriods + within7Days * 0.5) / judgedPeriods : 0;

    const totalPayments = paymentTimeline.length;
    const totalPaidAmount = roundMoney(
      paymentTimeline.reduce((sum, entry) => sum + entry.amount, 0)
    );
    const lastPaymentTs = paymentTimeline.reduce(
      (latest, entry) => (entry.timestampMs > latest ? entry.timestampMs : latest),
      0
    );
    const lastPaymentLabel = formatPaymentBadgeDate(lastPaymentTs);
    const lastPaymentAgeDays = lastPaymentTs ? toAgeDays(nowMs, lastPaymentTs) : null;
    const paymentsLast30 = paymentTimeline.filter(
      (entry) =>
        nowMs - entry.timestampMs <= CREDIT_BADGE_SETTINGS.paymentWindow30Days * PAYMENT_DAY_MS
    ).length;
    const paymentsLast60 = paymentTimeline.filter(
      (entry) =>
        nowMs - entry.timestampMs <= CREDIT_BADGE_SETTINGS.paymentWindow60Days * PAYMENT_DAY_MS
    ).length;
    const paymentsLast90 = paymentTimeline.filter(
      (entry) =>
        nowMs - entry.timestampMs <= CREDIT_BADGE_SETTINGS.paymentWindow90Days * PAYMENT_DAY_MS
    ).length;

    const monthKeys = new Set(
      paymentTimeline.map((entry) => getUtcMonthKey(entry.timestampMs)).filter(Boolean)
    );
    let streakMonths = 0;
    if (monthKeys.size > 0) {
      const cursor = new Date(nowMs);
      for (let index = 0; index < 12; index += 1) {
        const key = `${cursor.getUTCFullYear()}-${String(cursor.getUTCMonth() + 1).padStart(2, '0')}`;
        if (!monthKeys.has(key)) break;
        streakMonths += 1;
        cursor.setUTCMonth(cursor.getUTCMonth() - 1);
      }
    }

    const currentBalance = toFiniteNumber(balance, outstandingAmount);
    const normalizedBalance = Math.max(0, currentBalance);
    const normalizedCreditLimit = Math.max(0, toFiniteNumber(creditLimit, 0));
    const creditLimitActive = normalizedCreditLimit > 0;
    const creditLimitUtilization = creditLimitActive
      ? roundRatio((normalizedBalance / normalizedCreditLimit) * 100)
      : null;
    const limitStatusKey = creditLimitActive
      ? normalizedBalance > normalizedCreditLimit
        ? 'over_limit'
        : 'within_limit'
      : 'not_set';
    const limitStatusLabel =
      limitStatusKey === 'over_limit'
        ? 'Over Limit'
        : limitStatusKey === 'within_limit'
          ? 'Within Limit'
          : 'Limit Not Set';

    const customerTag = isNewCustomer ? 'insufficient_history' : null;
    paymentScore =
      isNewCustomer || paymentScore === null || paymentScore === undefined
        ? null
        : clamp(Math.round(toFiniteNumber(paymentScore, 0)), 0, 100);
    displayStatus = isNewCustomer ? NEW_CUSTOMER_STATUS : displayStatus;
    const nextBetterBand = getNextBetterBand(displayStatus?.key || '');
    const helper = buildStatusHelper({
      isNewCustomer,
      displayStatus,
      nextBetterBand,
      activeCycleStartDateKey,
      activeCycleDueDateKey,
      graceDays: normalizedGraceDays,
      nowDateKey,
      outstandingAmount,
    });
    const isDefaulter =
      !isNewCustomer &&
      String(displayStatus?.key || '')
        .trim()
        .toLowerCase() === 'defaulter';

    const badges = [];
    if (displayStatus) {
      badges.push({
        id: 'payment_status',
        label: displayStatus.label,
        shortLabel: displayStatus.label,
        tone: displayStatus.tone,
        description: displayStatus.description,
      });
    }
    if (!isNewCustomer && paymentScore !== null) {
      badges.unshift({
        id: 'payment_score',
        label: `Score ${Math.round(paymentScore)}/100`,
        shortLabel: String(Math.round(paymentScore)),
        tone: displayStatus?.tone || 'neutral',
        description:
          `${displayStatus?.label || 'Payment status'}. Payment score ${Math.round(paymentScore)}/100. ${displayStatus?.description || ''}`.trim(),
      });
    }
    if (creditLimitActive) {
      badges.push({
        id: 'credit_limit_status',
        label: limitStatusLabel,
        shortLabel: limitStatusKey === 'over_limit' ? 'Over Limit' : 'Limit OK',
        tone: limitStatusKey === 'over_limit' ? 'problem' : 'stable',
        description:
          limitStatusKey === 'over_limit'
            ? `Current balance Rs ${normalizedBalance.toFixed(2)} is above the manual credit limit of Rs ${normalizedCreditLimit.toFixed(2)}.`
            : `Current balance Rs ${normalizedBalance.toFixed(2)} is within the manual credit limit of Rs ${normalizedCreditLimit.toFixed(2)}.`,
      });
    }
    if (missedPeriods > 0) {
      badges.push({
        id: 'missed_periods',
        label: `Missed ${missedPeriods}`,
        shortLabel: `Missed ${missedPeriods}`,
        tone: 'problem',
        description: `${missedPeriods} payment period${missedPeriods === 1 ? '' : 's'} fell beyond the grace threshold.`,
      });
    }
    if (outstandingAmount > EPSILON) {
      badges.push({
        id: 'oldest_due',
        label: `Oldest due ${oldestOpenDays}d`,
        shortLabel: `${Math.round(oldestOpenDays)}d Due`,
        tone: getOutstandingTone(oldestOpenDays),
        description: `Oldest unpaid credit period is ${Math.round(oldestOpenDays)} days old.`,
      });
    }

    const summaryParts = [];
    if (displayStatus?.label) summaryParts.push(displayStatus.label);
    if (paymentScore !== null) summaryParts.push(`Score ${Math.round(paymentScore)}/100`);
    if (activeCycleDueDateKey)
      summaryParts.push(
        `Current due ${formatPaymentBadgeDate(dateKeyToUtcMs(activeCycleDueDateKey))}`
      );
    if (missedPeriods > 0) summaryParts.push(`Missed ${missedPeriods}`);
    if (lastPaymentLabel) summaryParts.push(`Last paid ${lastPaymentLabel}`);
    if (outstandingAmount > EPSILON) summaryParts.push(`Due Rs ${normalizedBalance.toFixed(2)}`);
    if (creditLimitActive && limitStatusKey === 'over_limit') summaryParts.push('Over limit');

    return {
      periods: scoredPeriods,
      metrics: {
        is_active: normalizedIsActive,
        active_points: normalizedIsActive ? 30 : 0,
        discipline_points: roundRatio(positivePoints),
        missed_penalty: roundRatio(missedPenaltyPoints),
        delay_penalty: roundRatio(latePenaltyPoints),
        average_weight: roundRatio(averageWeight),
        raw_score_70: paymentScore === null ? 0 : roundRatio((paymentScore / 100) * 70),
        customer_tag: customerTag,
        total_periods: totalPeriods,
        judged_periods: judgedPeriods,
        on_time_periods: onTimePeriods,
        within_7d_periods: within7Days,
        within_30d_periods: within30Days,
        within_60d_periods: within60Days,
        late_periods: latePeriods,
        missed_periods: missedPeriods,
        average_delay_days: roundRatio(averageDelayDays),
        oldest_overdue_days: Math.round(oldestOverdueDays),
        unapplied_payment_amount: roundMoney(unappliedPaymentAmount),
      },
      badges,
      summary: {
        payment_score: paymentScore === null ? null : Math.round(paymentScore),
        payment_status: displayStatus?.key || null,
        payment_status_label: displayStatus?.label || null,
        payment_status_tone: displayStatus?.tone || null,
        payment_status_description: displayStatus?.description || null,
        payment_status_tag: null,
        is_defaulter: isDefaulter,
        customer_tag: customerTag,
        is_active: normalizedIsActive,
        active_points: normalizedIsActive ? 30 : 0,
        discipline_points: roundRatio(positivePoints),
        missed_penalty: roundRatio(missedPenaltyPoints),
        delay_penalty: roundRatio(latePenaltyPoints),
        average_weight: roundRatio(averageWeight),
        raw_score_70: paymentScore === null ? 0 : roundRatio((paymentScore / 100) * 70),
        score_basis_days: judgedPeriods > 0 ? roundRatio(averageDelayDays) : null,
        same_day_ratio: judgedPeriods > 0 ? roundRatio(onTimePeriods / judgedPeriods) : null,
        within_7d_ratio:
          judgedPeriods > 0 ? roundRatio((onTimePeriods + within7Days) / judgedPeriods) : null,
        within_30d_ratio:
          judgedPeriods > 0
            ? roundRatio((onTimePeriods + within7Days + within30Days) / judgedPeriods)
            : null,
        within_60d_ratio:
          judgedPeriods > 0
            ? roundRatio(
                (onTimePeriods + within7Days + within30Days + within60Days) / judgedPeriods
              )
            : null,
        average_delay_days: judgedPeriods > 0 ? roundRatio(averageDelayDays) : null,
        average_settlement_days: Number.isFinite(averageSettlementDays)
          ? roundRatio(averageSettlementDays)
          : null,
        current_balance: currentBalance,
        balance: currentBalance,
        outstanding_amount: outstandingAmount,
        maintain_score_by_date: activeCycleDueDateKey || null,
        oldest_open_days: outstandingAmount > EPSILON ? Math.round(oldestOpenDays) : 0,
        oldest_overdue_days: Math.round(oldestOverdueDays),
        open_entry_count: openPeriods.length,
        days_0_30: aging0To30,
        days_31_60: aging31To60,
        days_61_90: aging61To90,
        days_over_90: agingOver90,
        credit_limit: creditLimitActive ? normalizedCreditLimit : 0,
        credit_limit_active: creditLimitActive,
        credit_limit_utilization: creditLimitUtilization,
        limit_status: limitStatusKey,
        limit_status_label: limitStatusLabel,
        total_payments: totalPayments,
        total_paid_amount: totalPaidAmount,
        last_payment_at: lastPaymentTs ? new Date(lastPaymentTs).toISOString() : null,
        last_payment_label: lastPaymentLabel || null,
        last_payment_days: Number.isFinite(lastPaymentAgeDays) ? lastPaymentAgeDays : null,
        payments_30d: paymentsLast30,
        payments_60d: paymentsLast60,
        payments_90d: paymentsLast90,
        streak_months: streakMonths,
        total_periods: totalPeriods,
        judged_periods: judgedPeriods,
        on_time_periods: onTimePeriods,
        within_7d_periods: within7Days,
        within_30d_periods: within30Days,
        within_60d_periods: within60Days,
        late_periods: latePeriods,
        missed_periods: missedPeriods,
        grace_days: normalizedGraceDays,
        unapplied_payment_amount: roundMoney(unappliedPaymentAmount),
        status_target_days: Number(displayStatus?.target_days || DEFAULT_NEW_STATUS_DAYS),
        next_status_label: nextBetterBand?.label || null,
        helper_mode: helper.mode,
        helper_text: helper.text,
        summary_line: summaryParts.join(' · '),
      },
    };
  };

  const buildPaymentActivityBadges = (entries, options = {}) => {
    const profile = buildCreditDisciplineProfile(entries, options);
    return {
      badges: Array.isArray(profile?.badges) ? profile.badges : [],
      summary: profile?.summary || null,
      metrics: profile?.metrics || null,
    };
  };

  return {
    buildCreditDisciplineProfile,
    buildPaymentActivityBadges,
  };
};

module.exports = {
  CREDIT_BADGE_SETTINGS,
  SCORE_BANDS,
  createCreditBadgeUtils,
};

const createPhoneChangeApprove = (deps = {}) => {
  const {
    dbGetAsync,
    dbRunAsync,
    dbTxAsync,
    parsePhoneInput,
    normalizePhone,
    normalizePhoneChangeRequestStatus,
    PHONE_CHANGE_STATUS_PENDING,
    PHONE_CHANGE_STATUS_APPROVED,
    PHONE_CHANGE_DECISION_AUTO,
    PHONE_CHANGE_DECISION_ADMIN,
    getPhoneMergeImpactSummary,
    movePhoneLinkedIdentityRecords,
  } = deps;

  const approvePhoneChangeRequest = async ({
    id,
    reviewedBy = null,
    decisionSource = PHONE_CHANGE_DECISION_ADMIN,
    adminNote = null,
    allowConflictMerge = false,
  }) => {
    const requestId = Number(id || 0);
    if (!requestId) return null;
    const reviewedById = Number(reviewedBy || 0) || null;
    const source =
      String(decisionSource || '')
        .trim()
        .toUpperCase() === PHONE_CHANGE_DECISION_AUTO
        ? PHONE_CHANGE_DECISION_AUTO
        : PHONE_CHANGE_DECISION_ADMIN;

    return dbTxAsync(async () => {
      const requestRow = await dbGetAsync('SELECT * FROM phone_change_requests WHERE id = ?', [
        requestId,
      ]);
      if (!requestRow) return null;
      if (
        normalizePhoneChangeRequestStatus(requestRow.status, '') !== PHONE_CHANGE_STATUS_PENDING
      ) {
        const err = new Error(`Cannot approve request in status "${requestRow.status}"`);
        err.status = 400;
        throw err;
      }

      const owner = await dbGetAsync('SELECT id, phone FROM users WHERE id = ?', [
        requestRow.user_id,
      ]);
      if (!owner) {
        const err = new Error('User not found for this phone change request');
        err.status = 404;
        throw err;
      }

      const newPhoneParsed = parsePhoneInput(requestRow.new_phone, { required: true });
      if (newPhoneParsed.error) {
        const err = new Error(newPhoneParsed.error);
        err.status = 400;
        throw err;
      }
      const newPhone = newPhoneParsed.value;
      const currentOwnerPhone = normalizePhone(owner.phone);
      const conflictUser = await dbGetAsync(
        `SELECT id
         FROM users
         WHERE phone = ? AND id <> ?
         LIMIT 1`,
        [newPhone, owner.id]
      );

      if (source === PHONE_CHANGE_DECISION_AUTO && conflictUser) {
        const err = new Error('Conflict detected, requires admin review');
        err.status = 409;
        throw err;
      }

      const conflictUserId = Number(conflictUser?.id || 0) || null;
      let mergeImpact = null;
      if (conflictUserId) {
        mergeImpact = await getPhoneMergeImpactSummary(conflictUserId);
      }
      if (
        source === PHONE_CHANGE_DECISION_ADMIN &&
        conflictUserId &&
        !Boolean(allowConflictMerge)
      ) {
        const err = new Error('Conflict detected. Confirm identity merge to approve this request.');
        err.status = 409;
        err.code = 'PHONE_CONFLICT_REQUIRES_MERGE';
        err.details = {
          requires_merge_confirmation: true,
          conflict_user_id: conflictUserId,
          merge_impact: mergeImpact,
        };
        throw err;
      }
      if (conflictUserId) {
        await movePhoneLinkedIdentityRecords({ fromUserId: conflictUserId, toUserId: owner.id });
        await dbRunAsync(
          `UPDATE users
           SET phone = NULL,
               phone_verified = 0
           WHERE id = ?`,
          [conflictUserId]
        );
      }

      if (currentOwnerPhone !== newPhone) {
        await dbRunAsync(
          `UPDATE users
           SET phone = ?, phone_verified = 0
           WHERE id = ?`,
          [newPhone, owner.id]
        );
      }

      await dbRunAsync(
        `UPDATE phone_change_requests
         SET status = ?,
             needs_admin_review = 0,
             conflict_user_id = ?,
             decision_source = ?,
             admin_note = ?,
             rejection_reason = NULL,
             reviewed_by = ?,
             reviewed_at = CURRENT_TIMESTAMP,
             updated_at = CURRENT_TIMESTAMP
         WHERE id = ?`,
        [
          PHONE_CHANGE_STATUS_APPROVED,
          conflictUserId,
          source,
          adminNote ? String(adminNote).trim() : null,
          reviewedById,
          requestId,
        ]
      );

      const updatedRequest = await dbGetAsync('SELECT * FROM phone_change_requests WHERE id = ?', [
        requestId,
      ]);
      const updatedUser = await dbGetAsync('SELECT * FROM users WHERE id = ?', [owner.id]);
      return {
        request: updatedRequest,
        user: updatedUser,
        conflict_user_id: conflictUserId,
        merge_impact: mergeImpact,
        merge_identity_applied: Boolean(conflictUserId && allowConflictMerge),
      };
    });
  };

  return { approvePhoneChangeRequest };
};

module.exports = { createPhoneChangeApprove };

const { registerBillingUserRoutes } = require('./routes/billingUserRoutes');
const { registerBillingSearchRoutes } = require('./routes/billingSearchRoutes');
const { registerBillingCreateRoutes } = require('./routes/billingCreateRoutes');
const { registerBillingAdminRoutes } = require('./routes/billingAdminRoutes');

const registerBillingRoutes = (deps) => {
  const {
    app,
    requireAuth,
    requireAdmin,
    dbAllAsync,
    dbGetAsync,
    dbRunAsync,
    dbTxAsync,
    normalizeEmail,
    normalizePhone,
    normalizeOrderStatus,
    normalizePaymentMethod,
    normalizeProductRecord,
    ORDER_STATUS_ORDERED,
    ORDER_STATUS_RECEIVED,
    resolveClientRequestId,
    isUniqueViolationError,
    generateBillNumber,
    logStockLedgerAsync,
    logAdminAuditAsync,
    createAppNotification,
  } = deps;

  const normalizeUomToken = (value, fallback = 'pcs') =>
    String(value || fallback)
      .trim()
      .toLowerCase() || fallback;

  const UNIT_FAMILY_BASE_BY_UNIT = Object.freeze({
    pcs: 'pcs',
    dozen: 'pcs',
    kg: 'kg',
    g: 'kg',
    l: 'l',
    ml: 'l',
  });

  const UNIT_FAMILY_MULTIPLIERS = Object.freeze({
    pcs: Object.freeze({ pcs: 1, dozen: 12 }),
    kg: Object.freeze({ kg: 1, g: 0.001 }),
    l: Object.freeze({ l: 1, ml: 0.001 }),
  });

  const getUomFamily = (baseUnit = 'pcs') => {
    const normalizedBase = normalizeUomToken(baseUnit, 'pcs');
    const familyBase = UNIT_FAMILY_BASE_BY_UNIT[normalizedBase];
    if (!familyBase) return null;
    const multipliers = UNIT_FAMILY_MULTIPLIERS[familyBase];
    if (!multipliers || !Number.isFinite(multipliers[normalizedBase])) return null;
    return {
      normalizedBase,
      multipliers,
    };
  };

  const getAllowedUnitsFromBaseUnit = (baseUnit = 'pcs') => {
    const family = getUomFamily(baseUnit);
    if (!family) return [];
    const allUnits = Object.keys(family.multipliers);
    return [family.normalizedBase, ...allUnits.filter((unit) => unit !== family.normalizedBase)];
  };

  const convertQtyBetweenFamilyUnits = (qty, fromUnit, toUnit, baseUnit = 'pcs') => {
    const numericQty = Math.max(0, Number(qty || 0));
    if (numericQty <= 0) return 0;
    const family = getUomFamily(baseUnit);
    if (!family) return null;
    const from = normalizeUomToken(fromUnit, family.normalizedBase);
    const to = normalizeUomToken(toUnit, family.normalizedBase);
    const fromMultiplier = family.multipliers[from];
    const toMultiplier = family.multipliers[to];
    if (!Number.isFinite(fromMultiplier) || !Number.isFinite(toMultiplier) || toMultiplier <= 0) {
      return null;
    }
    const qtyInCanonicalBase = numericQty * fromMultiplier;
    return qtyInCanonicalBase / toMultiplier;
  };

  const normalizeUomType = (value) => {
    const token = String(value || '')
      .trim()
      .toLowerCase();
    return ['selling', 'purchasing', 'both'].includes(token) ? token : 'selling';
  };

  const getProductUomProfile = (product = null) => {
    const sellingUnit = normalizeUomToken(product?.uom, 'pcs');
    const baseUnit = normalizeUomToken(product?.base_unit, sellingUnit);
    const conversionFactorRaw = Number(product?.conversion_factor ?? 1);
    const conversionFactor =
      Number.isFinite(conversionFactorRaw) && conversionFactorRaw > 0 ? conversionFactorRaw : 1;
    return {
      sellingUnit,
      baseUnit,
      conversionFactor,
      uomType: normalizeUomType(product?.uom_type),
    };
  };

  const getAllowedBillingUnits = (product = null) => {
    const profile = getProductUomProfile(product);
    const familyUnits = getAllowedUnitsFromBaseUnit(profile.baseUnit);
    if (familyUnits.length) return familyUnits;
    if (profile.baseUnit === profile.sellingUnit) return [profile.baseUnit];
    return [...new Set([profile.baseUnit, profile.sellingUnit])];
  };

  const toStockUnitQty = (qty, unit, product = null) => {
    const numericQty = Math.max(0, Number(qty || 0));
    if (numericQty <= 0) return 0;
    const profile = getProductUomProfile(product);
    const inputUnit = normalizeUomToken(unit, profile.sellingUnit);
    const familyConverted = convertQtyBetweenFamilyUnits(
      numericQty,
      inputUnit,
      profile.baseUnit,
      profile.baseUnit
    );
    if (familyConverted !== null) return familyConverted;
    if (inputUnit === profile.baseUnit) return numericQty;
    if (inputUnit === profile.sellingUnit && profile.sellingUnit !== profile.baseUnit) {
      return numericQty / profile.conversionFactor;
    }
    return numericQty;
  };

  const fromStockUnitQty = (stockQty, unit, product = null) => {
    const numericQty = Math.max(0, Number(stockQty || 0));
    if (numericQty <= 0) return 0;
    const profile = getProductUomProfile(product);
    const outputUnit = normalizeUomToken(unit, profile.sellingUnit);
    const familyConverted = convertQtyBetweenFamilyUnits(
      numericQty,
      profile.baseUnit,
      outputUnit,
      profile.baseUnit
    );
    if (familyConverted !== null) return familyConverted;
    if (outputUnit === profile.baseUnit) return numericQty;
    if (outputUnit === profile.sellingUnit && profile.sellingUnit !== profile.baseUnit) {
      return numericQty * profile.conversionFactor;
    }
    return numericQty;
  };

  const roundQty = (value) => Number(Number(value || 0).toFixed(3));
  const toPricingQty = (qty, unit, product = null) => {
    const numericQty = Math.max(0, Number(qty || 0));
    if (numericQty <= 0) return 0;
    return product ? toStockUnitQty(numericQty, unit, product) : numericQty;
  };

  const routeDeps = {
    ...deps,
    normalizeUomToken,
    UNIT_FAMILY_BASE_BY_UNIT,
    UNIT_FAMILY_MULTIPLIERS,
    getUomFamily,
    getAllowedUnitsFromBaseUnit,
    convertQtyBetweenFamilyUnits,
    normalizeUomType,
    getProductUomProfile,
    getAllowedBillingUnits,
    toStockUnitQty,
    fromStockUnitQty,
    roundQty,
    toPricingQty,
  };

  registerBillingUserRoutes(routeDeps);
  registerBillingSearchRoutes(routeDeps);
  registerBillingCreateRoutes(routeDeps);
  registerBillingAdminRoutes(routeDeps);
};

module.exports = { registerBillingRoutes };

const {
  loadActiveOffers,
  loadProductsByIds,
  resolveOfferEligibilityContext,
  previewOfferPricing,
} = require('../offers/offerEngine');

const createOrderPlacement = (deps) => {
  const {
    dbAllAsync,
    dbGetAsync,
    dbRunAsync,
    dbTxAsync,
    normalizeEmail,
    parsePhoneInput,
    parseBooleanEnv,
    normalizePaymentMethod,
    generateOrderNumber,
    normalizeOrderPaymentStatus,
    ORDER_STATUS_ORDERED,
  } = deps;
  const { validateOrderPayload } = require('./orderPlacement/validatePayload');
  const { parseOrderItems } = require('./orderPlacement/parseItems');
  const { loadOrderStockSnapshots } = require('./orderPlacement/loadStockSnapshots');
  const { computeOrderTotals } = require('./orderPlacement/computeTotals');
  const { persistOrderPlacement } = require('./orderPlacement/persistOrder');

  const placeOrder = async (payload) => {
    const {
      user_id = null,
      customer_name,
      customer_email = '',
      customer_phone = null,
      shipping_address = {},
      items = [],
      payment_method = 'cash',
    } = payload;

    const { normalizedCustomerEmail, normalizedCustomerPhone } = await validateOrderPayload({
      payload,
      dbGetAsync,
      normalizeEmail,
      parsePhoneInput,
    });

    const parsedItems = parseOrderItems({ items, parseBooleanEnv });
    const { stockSnapshotByProductId } = await loadOrderStockSnapshots({
      parsedItems,
      dbGetAsync,
    });
    const pricedItems = await (async () => {
      const productIds = parsedItems
        .map((item) => Number(item?.product_id || 0))
        .filter((productId) => productId > 0);
      const [productsById, activeOffers] = await Promise.all([
        loadProductsByIds(dbAllAsync, productIds),
        loadActiveOffers(dbAllAsync),
      ]);
      const eligibilityContext = await resolveOfferEligibilityContext(dbGetAsync, {
        customer_user_id: Number(user_id || 0) || null,
      });
      const preview = previewOfferPricing({
        items: parsedItems.map((item) => ({
          client_item_id: item.line_index,
          product_id: Number(item?.product_id || 0) || null,
          product_name: item.product_name,
          quantity: Number(item.quantity || 0),
          unit: item.uom,
          unit_price_override:
            Number(item.is_manual || 0) === 1 ? Number(item.price || 0) : undefined,
          skip_offers: Number(item.is_manual || 0) === 1,
          item_type: Number(item.is_manual || 0) === 1 ? 'manual' : 'catalog',
          price_unknown: Number(item.is_manual || 0) === 1 && Number(item.price || 0) <= 0 ? 1 : 0,
        })),
        productsById,
        offers: activeOffers,
        offersArePrepared: true,
        eligibilityContext,
        includeTax: false,
      });
      const previewByIndex = new Map(
        (Array.isArray(preview?.items) ? preview.items : []).map((line) => [
          Number(line?.client_item_id),
          line,
        ])
      );
      return parsedItems.map((item) => {
        const line = previewByIndex.get(Number(item.line_index));
        if (!line) {
          return {
            ...item,
            line_subtotal: Math.max(0, Number(item.price || 0) * Number(item.quantity || 0)),
            line_total: Math.max(0, Number(item.price || 0) * Number(item.quantity || 0)),
            offer_discount: 0,
            manual_discount: 0,
            offer_label: null,
          };
        }
        const quantity = Math.max(1, Number(item.quantity || 0) || 1);
        const effectiveUnitPrice =
          quantity > 0 ? Math.round((Number(line.line_total || 0) / quantity) * 100) / 100 : 0;
        return {
          ...item,
          price: effectiveUnitPrice,
          line_subtotal: Math.max(0, Number(line.line_subtotal || 0)),
          line_total: Math.max(0, Number(line.line_total || 0)),
          offer_discount: Math.max(0, Number(line.auto_offer_discount || 0)),
          manual_discount: Math.max(0, Number(line.manual_discount || 0)),
          offer_label: String(line.best_offer_label || '').trim() || null,
        };
      });
    })();

    const totals = computeOrderTotals({
      parsedItems: pricedItems,
      paymentMethod: payment_method,
      normalizePaymentMethod,
      generateOrderNumber,
      ORDER_STATUS_ORDERED,
    });

    return persistOrderPlacement({
      dbRunAsync,
      dbTxAsync,
      normalizeOrderPaymentStatus,
      parsedItems: pricedItems,
      stockSnapshotByProductId,
      orderNumber: totals.orderNumber,
      userId: user_id,
      customerName: customer_name,
      customerEmail: normalizedCustomerEmail,
      customerPhone: normalizedCustomerPhone,
      shippingAddress: shipping_address,
      total: totals.total,
      createdStatus: totals.createdStatus,
      normalizedPaymentMethod: totals.normalizedPaymentMethod,
    });
  };

  return { placeOrder };
};

module.exports = { createOrderPlacement };

const registerBillingAdminRoutes = (deps) => {
  const {
    app,
    requireAuth,
    requireAdmin,
    requireCapability,
    dbAllAsync,
    dbGetAsync,
    dbRunAsync,
    dbTxAsync,
    normalizeEmail,
    normalizePhone,
    normalizeOrderStatus,
    normalizePaymentMethod,
    normalizeProductRecord,
    ORDER_STATUS_ORDERED,
    ORDER_STATUS_RECEIVED,
    resolveClientRequestId,
    isUniqueViolationError,
    generateBillNumber,
    logStockLedgerAsync,
    logAdminAuditAsync,
    createAppNotification,
    normalizeUomToken,
    UNIT_FAMILY_BASE_BY_UNIT,
    UNIT_FAMILY_MULTIPLIERS,
    getUomFamily,
    getAllowedUnitsFromBaseUnit,
    convertQtyBetweenFamilyUnits,
    normalizeUomType,
    getProductUomProfile,
    getAllowedBillingUnits,
    toStockUnitQty,
    fromStockUnitQty,
    roundQty,
    toPricingQty,
  } = deps;

  app.get(
    '/api/bills',
    requireCapability('view_backoffice', 'Backoffice access required'),
    async (req, res) => {
      try {
        const query = String(req.query?.q || '').trim();
        const billType = String(req.query?.bill_type || '')
          .trim()
          .toLowerCase();
        const dateKey = String(req.query?.date || '').trim();
        const wantsPaginated = ['1', 'true', 'yes'].includes(
          String(req.query?.paginated || '')
            .trim()
            .toLowerCase()
        );
        const page = Math.max(1, Number.parseInt(req.query?.page, 10) || 1);
        const limit = Math.min(100, Math.max(1, Number.parseInt(req.query?.limit, 10) || 50));
        const offset = (page - 1) * limit;
        const clauses = [];
        const params = [];

        if (query) {
          clauses.push(`(
        bill_number LIKE ?
        OR customer_name LIKE ?
        OR customer_email LIKE ?
        OR customer_phone LIKE ?
        OR CAST(id AS TEXT) LIKE ?
      )`);
          params.push(`%${query}%`, `%${query}%`, `%${query}%`, `%${query}%`, `%${query}%`);
        }
        if (billType) {
          clauses.push(`LOWER(COALESCE(bill_type, 'sales')) = ?`);
          params.push(billType);
        }
        if (dateKey) {
          clauses.push(`DATE(created_at) = DATE(?)`);
          params.push(dateKey);
        }

        const whereClause = clauses.length ? `WHERE ${clauses.join(' AND ')}` : '';
        const baseQuery = `SELECT * FROM bills ${whereClause} ORDER BY created_at DESC`;

        if (!wantsPaginated) {
          return res.json(await dbAllAsync(baseQuery, params));
        }

        const [items, totalRow] = await Promise.all([
          dbAllAsync(`${baseQuery} LIMIT ? OFFSET ?`, [...params, limit, offset]),
          dbGetAsync(`SELECT COUNT(*) AS total FROM bills ${whereClause}`, params),
        ]);

        return res.json({
          items,
          page,
          limit,
          total: Number(totalRow?.total || 0),
        });
      } catch (error) {
        return res.status(500).json({ error: error.message });
      }
    }
  );

  app.get(
    '/api/bills/:id',
    requireCapability('view_backoffice', 'Backoffice access required'),
    async (req, res) => {
      try {
        const id = req.params.id;
        const bill = await dbGetAsync(`SELECT * FROM bills WHERE id = ? OR bill_number = ?`, [
          id,
          id,
        ]);
        if (!bill) return res.status(404).json({ error: 'Bill not found' });
        const items = await dbAllAsync(`SELECT * FROM bill_items WHERE bill_id = ?`, [bill.id]);
        return res.json({ ...bill, items });
      } catch (error) {
        return res.status(500).json({ error: error.message });
      }
    }
  );

  app.delete(
    '/api/bills/:id',
    requireCapability('delete_bills', 'Bill deletion access required'),
    async (req, res) => {
      try {
        const existing = await dbGetAsync(`SELECT * FROM bills WHERE id = ?`, [req.params.id]);
        if (!existing) return res.status(404).json({ error: 'Bill not found' });
        await dbTxAsync(async () => {
          await dbRunAsync(`DELETE FROM bill_items WHERE bill_id = ?`, [req.params.id]);
          await dbRunAsync(`DELETE FROM bills WHERE id = ?`, [req.params.id]);
        });
        await logAdminAuditAsync(req, {
          action: 'bill.delete',
          entityType: 'bill',
          entityId: req.params.id,
          details: {
            bill_number: existing.bill_number || null,
            total_amount: Number(existing.total_amount || 0),
            order_id: Number(existing.order_id || 0) || null,
          },
        });
        return res.json({ success: true });
      } catch (error) {
        return res.status(500).json({ error: error.message });
      }
    }
  );

  app.put('/api/bills/:id/payment', requireAdmin, async (req, res) => {
    try {
      const cur = await dbGetAsync(`SELECT * FROM bills WHERE id = ?`, [req.params.id]);
      if (!cur) return res.status(404).json({ error: 'Bill not found' });
      const nextPaymentStatus =
        String(req.body?.payment_status || cur.payment_status || '')
          .trim()
          .toLowerCase() || 'pending';
      const nextPaymentMethod = normalizePaymentMethod(
        req.body?.payment_method || cur.payment_method
      );
      await dbRunAsync(
        `UPDATE bills SET payment_status = ?, payment_method = ?, updated_at=CURRENT_TIMESTAMP WHERE id = ?`,
        [nextPaymentStatus, nextPaymentMethod, req.params.id]
      );
      const linkedOrderId = Number(cur.order_id || 0);
      if (linkedOrderId) {
        await dbRunAsync(
          `UPDATE orders
         SET payment_status = ?, credit_applied = ?
         WHERE id = ?`,
          [
            nextPaymentStatus,
            nextPaymentStatus === 'paid' ? 0 : Number(cur.credit_amount || 0) > 0 ? 1 : 0,
            linkedOrderId,
          ]
        );
      }
      await logAdminAuditAsync(req, {
        action: 'bill.payment_update',
        entityType: 'bill',
        entityId: req.params.id,
        details: {
          payment_status: nextPaymentStatus,
          payment_method: nextPaymentMethod,
          linked_order_id: linkedOrderId || null,
        },
      });
      return res.json({ success: true });
    } catch (error) {
      return res.status(500).json({ error: error.message });
    }
  });

  app.get(
    '/api/bills/stats/summary',
    requireCapability('view_backoffice', 'Backoffice access required'),
    async (_, res) => {
      try {
        const totalBills = (await dbGetAsync(`SELECT COUNT(*) as count FROM bills`))?.count || 0;
        const totalSales =
          (
            await dbGetAsync(
              `SELECT COALESCE(SUM(total_amount),0) as total FROM bills WHERE bill_type = 'sales'`
            )
          )?.total || 0;
        const totalPurchase =
          (
            await dbGetAsync(
              `SELECT COALESCE(SUM(total_amount),0) as total FROM bills WHERE bill_type = 'purchase'`
            )
          )?.total || 0;
        return res.json({ totalBills, totalSales, totalPurchase });
      } catch (error) {
        return res.status(500).json({ error: error.message });
      }
    }
  );
};

module.exports = { registerBillingAdminRoutes };

const { loadActiveOffers, decorateProductWithOffers } = require('../../offers/offerEngine');
const { createBillingSearchHelpers } = require('./billingSearch/billingSearchHelpers');
const { sendRouteError } = require('../../../core/routeErrors');

const registerBillingSearchRoutes = (deps) => {
  const {
    app,
    requireAuth,
    requireAdmin,
    dbAllAsync,
    dbGetAsync,
    dbRunAsync,
    dbTxAsync,
    normalizeEmail,
    normalizePhone,
    normalizeOrderStatus,
    normalizePaymentMethod,
    normalizeProductRecord,
    ORDER_STATUS_ORDERED,
    ORDER_STATUS_RECEIVED,
    resolveClientRequestId,
    isUniqueViolationError,
    generateBillNumber,
    logStockLedgerAsync,
    logAdminAuditAsync,
    createAppNotification,
    normalizeUomToken,
    UNIT_FAMILY_BASE_BY_UNIT,
    UNIT_FAMILY_MULTIPLIERS,
    getUomFamily,
    getAllowedUnitsFromBaseUnit,
    convertQtyBetweenFamilyUnits,
    normalizeUomType,
    getProductUomProfile,
    getAllowedBillingUnits,
    toStockUnitQty,
    fromStockUnitQty,
    roundQty,
    toPricingQty,
  } = deps;

  const { getBillingProductSelectColumns, enrichRowsWithPurchaseCost } = createBillingSearchHelpers(
    {
      dbAllAsync,
      dbGetAsync,
    }
  );

  app.get('/api/billing/customers/search', requireAdmin, async (req, res) => {
    try {
      const q = String(req.query.q || '').trim();
      const like = `%${q}%`;
      const rows = q
        ? await dbAllAsync(
            `SELECT id, name, email, phone, address FROM users WHERE role='customer' AND (name LIKE ? OR email LIKE ? OR phone LIKE ?) ORDER BY name LIMIT 20`,
            [like, like, like]
          )
        : await dbAllAsync(
            `SELECT id, name, email, phone, address FROM users WHERE role='customer' ORDER BY name LIMIT 20`
          );
      return res.json(rows);
    } catch (error) {
      return sendRouteError(res, error, { fallbackMessage: 'Failed to search customers' });
    }
  });

  app.get('/api/billing/products/search', requireAdmin, async (req, res) => {
    try {
      const q = String(req.query.q || '').trim();
      const category = String(req.query.category || '').trim();
      const normalizedQuery = q.toLowerCase();
      const requestedLimit = Math.max(
        1,
        Math.min(10, Math.floor(Number(req.query.limit || 8) || 8))
      );
      const includeCosts = String(req.query.include_costs || '').trim() === '1';
      const exactOnly = String(req.query.exact_only || '').trim() === '1';

      if (!normalizedQuery) {
        return res.json([]);
      }

      const selectColumns = await getBillingProductSelectColumns();

      const categoryWhere = category ? ` AND category = ?` : '';
      const categoryParams = category ? [category] : [];

      const exactRows = await dbAllAsync(
        `
        SELECT ${selectColumns}
        FROM products
        WHERE COALESCE(is_active, 1) = 1
          ${categoryWhere}
          AND (
            LOWER(COALESCE(barcode, '')) = ?
            OR LOWER(COALESCE(sku, '')) = ?
            OR LOWER(COALESCE(name, '')) = ?
          )
        ORDER BY
          CASE
            WHEN LOWER(COALESCE(barcode, '')) = ? THEN 0
            WHEN LOWER(COALESCE(sku, '')) = ? THEN 1
            ELSE 2
          END,
          name
        LIMIT ?
      `,
        [
          ...categoryParams,
          normalizedQuery,
          normalizedQuery,
          normalizedQuery,
          normalizedQuery,
          normalizedQuery,
          requestedLimit,
        ]
      );

      let rows = exactRows;

      const shouldRunFuzzySearch = !exactOnly && normalizedQuery.length >= 2;

      if (rows.length < requestedLimit && shouldRunFuzzySearch) {
        const fuzzyLike = `%${normalizedQuery}%`;
        const prefixLike = `${normalizedQuery}%`;
        const exactIds = rows.map((row) => Number(row?.id || 0)).filter((id) => id > 0);

        let fuzzySql = `
        SELECT ${selectColumns}
        FROM products
        WHERE COALESCE(is_active, 1) = 1
          ${categoryWhere}
          AND (
            LOWER(COALESCE(name, '')) LIKE ?
            OR LOWER(COALESCE(sku, '')) LIKE ?
            OR LOWER(COALESCE(brand, '')) LIKE ?
            OR LOWER(COALESCE(barcode, '')) LIKE ?
          )
      `;
        const fuzzyParams = [...categoryParams, fuzzyLike, fuzzyLike, fuzzyLike, fuzzyLike];

        if (exactIds.length > 0) {
          fuzzySql += ` AND id NOT IN (${exactIds.map(() => '?').join(', ')})`;
          fuzzyParams.push(...exactIds);
        }

        fuzzySql += `
        ORDER BY
          CASE
            WHEN LOWER(COALESCE(barcode, '')) LIKE ? THEN 0
            WHEN LOWER(COALESCE(sku, '')) LIKE ? THEN 1
            WHEN LOWER(COALESCE(name, '')) LIKE ? THEN 2
            WHEN LOWER(COALESCE(brand, '')) LIKE ? THEN 3
            ELSE 4
          END,
          name
        LIMIT ?
      `;

        fuzzyParams.push(
          prefixLike,
          prefixLike,
          prefixLike,
          prefixLike,
          requestedLimit - rows.length
        );

        const fuzzyRows = await dbAllAsync(fuzzySql, fuzzyParams);
        rows = rows.concat(fuzzyRows);
      }

      const [finalRows, activeOffers] = await Promise.all([
        includeCosts ? enrichRowsWithPurchaseCost(rows) : Promise.resolve(rows),
        loadActiveOffers(dbAllAsync),
      ]);
      return res.json(
        finalRows.map((row) =>
          decorateProductWithOffers(normalizeProductRecord(row), activeOffers, {
            offersArePrepared: true,
          })
        )
      );
    } catch (error) {
      return sendRouteError(res, error, { fallbackMessage: 'Failed to search products' });
    }
  });
};

