const buildPaymentDeliveryForecast = ({
  completedOrders,
  openDistributorOrders,
  payablesByDistributor,
  distributorId,
  ledgerBalanceByDistributor,
  computeAverageDays,
  getDistributorPaymentPlan,
  getPurchaseOrderPaymentAnchorDateKey,
  getPurchaseOrderAnchorDateKey,
  distributor,
  normalizeTransactionDate,
  addDaysToDateKey,
  pickEarliestDateKey,
  pickLatestDateKey,
  paymentLagDays,
  deliveryLagDays,
  paymentDateKeys,
  deliveryDateKeys,
  lastOrderDateKey,
} = {}) => {
  const openPayables = payablesByDistributor.get(distributorId) || [];
  const outstandingAmount = openDistributorOrders.reduce(
    (sum, order) => sum + Math.max(0, Number(order.balance_due || 0)),
    0
  );
  const configuredPaymentPlan = getDistributorPaymentPlan(distributor);
  const avgPaymentLagDays = computeAverageDays(paymentLagDays);
  const avgDeliveryDays = computeAverageDays(deliveryLagDays);
  const paymentReferenceOrder =
    completedOrders.find((order) => Number(order.balance_due || 0) > 0) ||
    completedOrders[0] ||
    null;
  const paymentAnchorDate = paymentReferenceOrder
    ? getPurchaseOrderPaymentAnchorDateKey(paymentReferenceOrder)
    : null;
  const inferredDueDate = paymentAnchorDate
    ? addDaysToDateKey(paymentAnchorDate, avgPaymentLagDays ?? configuredPaymentPlan.paymentDueDays)
    : null;
  const nextPaymentDueDate =
    pickEarliestDateKey(openPayables.map((entry) => entry.payment_due_date)) ||
    inferredDueDate ||
    null;
  const nextPaymentDueSource = openPayables.length
    ? 'open_payable'
    : inferredDueDate
      ? 'history_inferred'
      : 'unknown';
  const predictedPaymentAmount = nextPaymentDueDate
    ? openPayables
        .filter((entry) => entry.payment_due_date === nextPaymentDueDate)
        .reduce((sum, entry) => sum + Number(entry.balance_due || 0), 0)
    : 0;
  const openDeliveryDates = openDistributorOrders
    .map((order) => normalizeTransactionDate(order.expected_delivery || null))
    .filter(Boolean);
  const inferredDeliveryDate =
    avgDeliveryDays && lastOrderDateKey
      ? addDaysToDateKey(lastOrderDateKey, avgDeliveryDays)
      : null;
  const nextDeliveryDate = pickEarliestDateKey(openDeliveryDates) || inferredDeliveryDate || null;
  const nextDeliverySource = openDeliveryDates.length
    ? 'open_order'
    : inferredDeliveryDate
      ? 'history_inferred'
      : 'unknown';
  const predictedDeliveryCount = nextDeliveryDate
    ? openDistributorOrders.filter(
        (order) => normalizeTransactionDate(order.expected_delivery || null) === nextDeliveryDate
      ).length
    : 0;

  return {
    outstandingAmount,
    ledgerBalance: Number(ledgerBalanceByDistributor.get(distributorId) || 0),
    lastDeliveryDate: pickLatestDateKey(deliveryDateKeys),
    lastPaymentDate: pickLatestDateKey(paymentDateKeys),
    nextPaymentDueDate,
    nextPaymentDueSource,
    predictedPaymentAmount,
    nextDeliveryDate,
    nextDeliverySource,
    predictedDeliveryCount,
    configuredPaymentDueDays: configuredPaymentPlan.paymentDueDays,
    inferredPaymentDueDays: avgPaymentLagDays,
    avgDeliveryDays,
    inferredDueDate: inferredDueDate || null,
  };
};

module.exports = { buildPaymentDeliveryForecast };

const buildSupplierVisitKey = (supplierId, dateKey) =>
  `${Number(supplierId || 0)}@@${String(dateKey || '').trim()}`;

const buildSupplierVisitStates = ({
  baseData,
  metrics,
  weeklyDistributors,
  addDaysToDateKey,
  getSupplierScheduleConfig,
  getWeekdayFromDateKey,
  getPurchaseOrderLifecycleStatus,
  normalizeTransactionDate,
  PO_LIFECYCLE_CONFIRMED,
  PO_LIFECYCLE_PART_PAID,
  PO_LIFECYCLE_FULLY_PAID,
  PO_LIFECYCLE_CLOSED,
} = {}) => {
  const { todayKey, boardEndKey, distributors, suppliers, payments, supplierVisits } =
    baseData || {};
  const { enrichedOrders } = metrics || {};

  const doneLifecycleStatuses = new Set(
    [
      PO_LIFECYCLE_CONFIRMED,
      PO_LIFECYCLE_PART_PAID,
      PO_LIFECYCLE_FULLY_PAID,
      PO_LIFECYCLE_CLOSED,
    ].filter(Boolean)
  );
  const supplierById = new Map(
    (Array.isArray(suppliers) ? suppliers : []).map((entry) => [Number(entry?.id || 0), entry])
  );
  const distributorById = new Map(
    (Array.isArray(distributors) ? distributors : []).map((entry) => [
      Number(entry?.id || 0),
      entry,
    ])
  );
  const supplierVisitMap = new Map();

  const registerSupplierVisit = (supplierIdValue, dateValue, extra = {}) => {
    const supplierId = Number(supplierIdValue || 0);
    const dateKey = normalizeTransactionDate(dateValue || null);
    if (!supplierId || !dateKey) return;
    if (todayKey && dateKey < todayKey) return;
    if (boardEndKey && dateKey > boardEndKey) return;
    const supplier = supplierById.get(supplierId) || null;
    const distributorId = Number(extra?.distributor_id || supplier?.distributor_id || 0) || null;
    const distributor = distributorId ? distributorById.get(distributorId) || null : null;
    const key = buildSupplierVisitKey(supplierId, dateKey);
    if (supplierVisitMap.has(key)) return;
    supplierVisitMap.set(key, {
      supplier_id: supplierId,
      distributor_id: distributorId,
      supplier_name: extra?.supplier_name || supplier?.name || null,
      distributor_name: extra?.distributor_name || distributor?.name || null,
      date: dateKey,
    });
  };

  const activeSuppliers = (Array.isArray(suppliers) ? suppliers : [])
    .filter((supplier) => Number(supplier?.id || 0) > 0)
    .filter((supplier) => Boolean(supplier?.is_active ?? true))
    .filter((supplier) => {
      const distributor = distributorById.get(Number(supplier?.distributor_id || 0));
      return (
        distributor &&
        String(distributor?.status || 'active')
          .trim()
          .toLowerCase() === 'active'
      );
    });

  activeSuppliers.forEach((supplier) => {
    const distributor = distributorById.get(Number(supplier?.distributor_id || 0));
    const schedule =
      typeof getSupplierScheduleConfig === 'function'
        ? getSupplierScheduleConfig(supplier, distributor)
        : { scheduleType: 'irregular', scheduleDay: null };
    if (schedule?.scheduleType === 'daily') {
      for (let offset = 0; offset <= 6; offset += 1) {
        registerSupplierVisit(supplier.id, addDaysToDateKey(todayKey, offset), {
          distributor_id: supplier.distributor_id,
        });
      }
    }
  });

  (Array.isArray(weeklyDistributors) ? weeklyDistributors : []).forEach((entry) => {
    registerSupplierVisit(entry?.supplier_id, entry?.schedule_date, {
      distributor_id: entry?.distributor_id,
      supplier_name: entry?.supplier_name,
      distributor_name: entry?.distributor_name,
    });
  });

  (Array.isArray(enrichedOrders) ? enrichedOrders : []).forEach((order) => {
    registerSupplierVisit(order?.supplier_id, order?.planned_order_date, {
      distributor_id: order?.distributor_id,
      supplier_name: order?.supplier_name,
      distributor_name: order?.distributor_name,
    });
  });

  (Array.isArray(payments) ? payments : []).forEach((payment) => {
    registerSupplierVisit(payment?.supplier_id, payment?.transaction_date || payment?.created_at, {
      distributor_id: payment?.distributor_id,
      supplier_name: payment?.supplier_name,
      distributor_name: payment?.distributor_name,
    });
  });

  (Array.isArray(supplierVisits) ? supplierVisits : []).forEach((visit) => {
    registerSupplierVisit(visit?.supplier_id, visit?.visit_date, {
      distributor_id: visit?.distributor_id,
      supplier_name: visit?.supplier_name,
      distributor_name: visit?.distributor_name,
    });
  });

  const poDoneKeys = new Set();
  (Array.isArray(enrichedOrders) ? enrichedOrders : []).forEach((order) => {
    const lifecycleStatus = getPurchaseOrderLifecycleStatus(order);
    if (!doneLifecycleStatuses.has(lifecycleStatus)) return;
    const supplierId = Number(order?.supplier_id || 0);
    const dateKey = normalizeTransactionDate(order?.planned_order_date || null);
    if (!supplierId || !dateKey) return;
    poDoneKeys.add(buildSupplierVisitKey(supplierId, dateKey));
  });

  const paymentDoneKeys = new Set();
  (Array.isArray(payments) ? payments : []).forEach((payment) => {
    const supplierId = Number(payment?.supplier_id || 0);
    const dateKey = normalizeTransactionDate(
      payment?.transaction_date || payment?.created_at || null
    );
    if (!supplierId || !dateKey) return;
    if (Number(payment?.amount || 0) <= 0) return;
    paymentDoneKeys.add(buildSupplierVisitKey(supplierId, dateKey));
  });

  const closedVisitKeys = new Set();
  (Array.isArray(supplierVisits) ? supplierVisits : []).forEach((visit) => {
    const supplierId = Number(visit?.supplier_id || 0);
    const dateKey = normalizeTransactionDate(visit?.visit_date || null);
    if (!supplierId || !dateKey) return;
    if (!visit?.visit_closed) return;
    closedVisitKeys.add(buildSupplierVisitKey(supplierId, dateKey));
  });

  return Array.from(supplierVisitMap.values())
    .map((entry) => {
      const key = buildSupplierVisitKey(entry.supplier_id, entry.date);
      const poDone = poDoneKeys.has(key);
      const paymentDone = paymentDoneKeys.has(key);
      const visitClosed = closedVisitKeys.has(key);
      return {
        ...entry,
        poDone,
        paymentDone,
        visitClosed,
        isHandled: poDone || visitClosed,
      };
    })
    .sort(
      (left, right) =>
        String(left.date || '').localeCompare(String(right.date || '')) ||
        String(left.distributor_name || '').localeCompare(String(right.distributor_name || '')) ||
        String(left.supplier_name || '').localeCompare(String(right.supplier_name || ''))
    );
};

module.exports = { buildSupplierVisitStates };

const createPurchaseOperationsWorker = (deps) => {
  const {
    dbAllAsync,
    dbGetAsync,
    dbRunAsync,
    normalizeTransactionDate,
    addDaysToDateKey,
    normalizeBooleanFlag,
    getDistributorOrderScheduleDay,
    getPurchaseOrderLifecycleStatus,
    isPoEditableLifecycle,
    getWeekdayFromDateKey,
    parseDistributorProductsSupplied,
    mergeDistributorProductKnowledge,
    getDistributorPaymentPlan,
    computeAverageDays,
    computeAverageGapDays,
    computeStdDev,
    deriveStockoutRisk,
    getPurchaseOrderPaymentAnchorDateKey,
    getPurchaseOrderAnchorDateKey,
    getPurchaseOrderDeliveryDateKey,
    getDaysBetweenDateKeys,
    pickLatestDateKey,
    pickEarliestDateKey,
    normalizePoPaymentStatus,
    getEffectivePurchaseDueDateKey,
    resolveRollupRange,
    buildDateSeries,
    normalizePoLifecycleStatus,
    resolveInsightDateRange,
    notifyAdmins,
    PURCHASE_ACTION_ROLLUP_FIELDS,
    PURCHASE_ACTION_STATUS_MAP,
    PURCHASE_WEEKDAYS,
    PO_LIFECYCLE_PREPARED,
    PO_LIFECYCLE_SENT,
    PO_LIFECYCLE_REVISED,
    PO_LIFECYCLE_CANCELLED,
    PO_LIFECYCLE_FULLY_PAID,
    PO_LIFECYCLE_CLOSED,
    PO_PAYMENT_UNPAID,
    derivePurchaseNextAction,
    buildPurchaseActionRollupsAsync,
    persistPurchaseAnalyticsSnapshotsAsync,
    PURCHASE_OPERATIONS_NOTIFICATIONS_ENABLED,
    PURCHASE_OPERATIONS_NOTIFICATION_INTERVAL_MS,
    IS_VERCEL_RUNTIME,
    runPurchaseOperationNotificationsAsync,
    collectPurchaseAnalyticsSnapshotsAsync,
  } = deps;

  let purchaseOperationsNotificationTimer = null;

  const runPurchaseOperationsNotificationWorker = async () => {
    let result = null;
    try {
      if (PURCHASE_OPERATIONS_NOTIFICATIONS_ENABLED) {
        result = await runPurchaseOperationNotificationsAsync();
        const totalNotifications =
          Number(result?.reminder_notifications || 0) + Number(result?.payment_notifications || 0);
        if (totalNotifications > 0) {
          console.log(
            `[PURCHASE_OPS] Generated ${totalNotifications} purchase notifications for ${result.today}`
          );
        }
      }
      await collectPurchaseAnalyticsSnapshotsAsync();
      return result;
    } catch (error) {
      console.warn('[PURCHASE_OPS] Notification worker failed:', error?.message || error);
      return null;
    }
  };

  const startPurchaseOperationsNotificationWorker = () => {
    if (IS_VERCEL_RUNTIME) return;
    if (purchaseOperationsNotificationTimer) return;
    purchaseOperationsNotificationTimer = setInterval(() => {
      void runPurchaseOperationsNotificationWorker();
    }, PURCHASE_OPERATIONS_NOTIFICATION_INTERVAL_MS);
    void runPurchaseOperationsNotificationWorker();
  };

  const stopPurchaseOperationsNotificationWorker = () => {
    if (!purchaseOperationsNotificationTimer) return;
    clearInterval(purchaseOperationsNotificationTimer);
    purchaseOperationsNotificationTimer = null;
  };

  return {
    runPurchaseOperationsNotificationWorker,
    startPurchaseOperationsNotificationWorker,
    stopPurchaseOperationsNotificationWorker,
  };
};

module.exports = { createPurchaseOperationsWorker };
